import {useEffect, useRef} from 'react';
import {Coordinates, subtract} from '@dnd-kit/utilities';

import {defaultCoordinates} from '../../utilities';

export function useScrollOffsetsDelta(
  scrollOffsets: Coordinates,
  dependencies: any[] = []
) {
  const initialScrollOffsets = useRef<Coordinates | null>(null);

  useEffect(
    () => {
      initialScrollOffsets.current = null;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    dependencies
  );

  useEffect(() => {
    const hasScrollOffsets = scrollOffsets !== defaultCoordinates;

    if (hasScrollOffsets && !initialScrollOffsets.current) {
      initialScrollOffsets.current = scrollOffsets;
    }

    if (!hasScrollOffsets && initialScrollOffsets.current) {
      initialScrollOffsets.current = null;
    }
  }, [scrollOffsets]);

  return initialScrollOffsets.current
    ? subtract(scrollOffsets, initialScrollOffsets.current)
    : defaultCoordinates;
}

import {useEffect} from 'react';
import {canUseDOM} from '@dnd-kit/utilities';

import type {SensorDescriptor} from '../../sensors';

export function useSensorSetup(sensors: SensorDescriptor<any>[]) {
  useEffect(
    () => {
      if (!canUseDOM) {
        return;
      }

      const teardownFns = sensors.map(({sensor}) => sensor.setup?.());

      return () => {
        for (const teardown of teardownFns) {
          teardown?.();
        }
      };
    },
    // TO-DO: Sensors length could theoretically change which would not be a valid dependency
    // eslint-disable-next-line react-hooks/exhaustive-deps
    sensors.map(({sensor}) => sensor)
  );
}

import {useMemo} from 'react';

import type {SyntheticEventName, UniqueIdentifier} from '../../types';

export type SyntheticListener = {
  eventName: SyntheticEventName;
  handler: (event: React.SyntheticEvent, id: UniqueIdentifier) => void;
};

export type SyntheticListeners = SyntheticListener[];

export type SyntheticListenerMap = Record<string, Function>;

export function useSyntheticListeners(
  listeners: SyntheticListeners,
  id: UniqueIdentifier
): SyntheticListenerMap {
  return useMemo(() => {
    return listeners.reduce<SyntheticListenerMap>(
      (acc, {eventName, handler}) => {
        acc[eventName] = (event: React.SyntheticEvent) => {
          handler(event, id);
        };

        return acc;
      },
      {} as SyntheticListenerMap
    );
  }, [listeners, id]);
}

