/*
 * Adds a dummy node to the graph and return v.
 */
function addDummyNode(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    type: 'root' | "edge" | "border" | "edge-label" | "edge-proxy" | "selfedge",
    attrs: Partial<NodeLabel>,
    name: string
): string {
    let v: string = name;
    while (graph.hasNode(v)) {
        v = uniqueId(name);
    }

    attrs.dummy = type;
    graph.setNode(v, attrs as NodeLabel);
    return v;
}

/*
 * Returns a new graph with only simple edges. Handles aggregation of data
 * associated with multi-edges.
 */
function simplify(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): Graph<GraphLabel, NodeLabel, EdgeLabel> {
    const simplified = new Graph<GraphLabel, NodeLabel, EdgeLabel>().setGraph(graph.graph());
    graph.nodes().forEach(v => simplified.setNode(v, graph.node(v)));
    graph.edges().forEach(e => {
        const simpleLabel: EdgeLabel = simplified.edge(e.v, e.w) || {weight: 0, minlen: 1};
        const label: EdgeLabel = graph.edge(e);
        simplified.setEdge(e.v, e.w, {
            weight: simpleLabel.weight! + label.weight!,
            minlen: Math.max(simpleLabel.minlen!, label.minlen!)
        });
    });
    return simplified;
}

function asNonCompoundGraph(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): Graph<GraphLabel, NodeLabel, EdgeLabel> {
    const simplified = new Graph<GraphLabel, NodeLabel, EdgeLabel>({multigraph: graph.isMultigraph()}).setGraph(graph.graph());
    graph.nodes().forEach(v => {
        if (!graph.children(v).length) {
            simplified.setNode(v, graph.node(v));
        }
    });
    graph.edges().forEach(e => {
        simplified.setEdge(e, graph.edge(e));
    });
    return simplified;
}

function successorWeights(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): {
    [key: string]: { [key: string]: number }
} {
    const weightMap: { [key: string]: number }[] = graph.nodes().map(v => {
        const sucs: { [key: string]: number } = {};
        const outEdges = graph.outEdges(v);
        if (outEdges) {
            outEdges.forEach(e => {
                sucs[e.w] = (sucs[e.w] || 0) + graph.edge(e).weight!;
            });
        }
        return sucs;
    });
    return zipObject(graph.nodes(), weightMap);
}

function predecessorWeights(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): {
    [key: string]: { [key: string]: number }
} {
    const weightMap: { [key: string]: number }[] = graph.nodes().map(v => {
        const preds: { [key: string]: number } = {};
        const inEdges = graph.inEdges(v);
        if (inEdges) {
            inEdges.forEach(e => {
                preds[e.v] = (preds[e.v] || 0) + graph.edge(e).weight!;
            });
        }
        return preds;
    });
    return zipObject(graph.nodes(), weightMap);
}

/*
 * Finds where a line starting at point ({x, y}) would intersect a rectangle
 * ({x, y, width, height}) if it were pointing at the rectangle's center.
 */
function intersectRect(rect: NodeLabel, point: Point): Point {
    const x: number = rect.x!;
    const y: number = rect.y!;

    // Rectangle intersection algorithm from:
    // http://math.stackexchange.com/questions/108113/find-edge-between-two-boxes
    const dx: number = point.x - x;
    const dy: number = point.y - y;
    let w: number = rect.width / 2;
    let h: number = rect.height / 2;

    if (!dx && !dy) {
        throw new Error("Not possible to find intersection inside of the rectangle");
    }

    let sx: number, sy: number;
    if (Math.abs(dy) * w > Math.abs(dx) * h) {
        // Intersection is top or bottom of rect.
        if (dy < 0) {
            h = -h;
        }
        sx = h * dx / dy;
        sy = h;
    } else {
        // Intersection is left or right of rect.
        if (dx < 0) {
            w = -w;
        }
        sx = w;
        sy = w * dy / dx;
    }

    return {x: x + sx, y: y + sy};
}

/*
 * Given a DAG with each node assigned "rank" and "order" properties, this
 * function will produce a matrix with the ids of each node.
 */
function buildLayerMatrix(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): string[][] {
    const layering: string[][] = range(maxRank(graph) + 1).map(() => []);
    graph.nodes().forEach(v => {
        const node = graph.node(v) as NodeLabel;
        const rank: number | undefined = node.rank;
        if (rank !== undefined) {
            if (!layering[rank]) {
                layering[rank] = [];
            }
            layering[rank][node.order!] = v;
        }
    });
    return layering;
}

/*
 * Adjusts the ranks for all nodes in the graph such that all nodes v have
 * rank(v) >= 0 and at least one node w has rank(w) = 0.
 */
function normalizeRanks(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const nodeRanks: number[] = graph.nodes().map(v => {
        const rank: number | undefined = (graph.node(v) as NodeLabel).rank;
        if (rank === undefined) {
            return Number.MAX_VALUE;
        }

        return rank;
    });
    const min: number = applyWithChunking(Math.min, nodeRanks);
    graph.nodes().forEach(v => {
        const node = graph.node(v) as NodeLabel;
        if (Object.hasOwn(node, "rank")) {
            (node as NodeLabel).rank! -= min;
        }
    });
}

function removeEmptyRanks(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    // Ranks may not start at 0, so we need to offset them
    const nodeRanks: number[] = graph.nodes().map(v => graph.node(v).rank).filter((rank): rank is number => rank !== undefined);
    const offset: number = applyWithChunking(Math.min, nodeRanks);

    const layers: string[][] = [];
    graph.nodes().forEach(v => {
        const rank: number = graph.node(v).rank! - offset;
        if (!layers[rank]) {
            layers[rank] = [];
        }
        layers[rank].push(v);
    });

    let delta: number = 0;
    const nodeRankFactor: number = graph.graph().nodeRankFactor!;
    Array.from(layers).forEach((vs, i) => {
        if (vs === undefined && i % nodeRankFactor !== 0) {
            --delta;
        } else if (vs !== undefined && delta) {
            vs.forEach(v => graph.node(v).rank! += delta);
        }
    });
}

function addBorderNode(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    prefix: string,
    rank?: number,
    order?: number
): string {
    const node: Partial<NodeLabel> = {
        width: 0,
        height: 0
    };
    if (arguments.length >= 4) {
        node.rank = rank;
        node.order = order;
    }
    return addDummyNode(graph, "border", node, prefix);
}

function splitToChunks<T>(array: T[], chunkSize: number = CHUNKING_THRESHOLD): T[][] {
    const chunks: T[][] = [];
    for (let i = 0; i < array.length; i += chunkSize) {
        const chunk: T[] = array.slice(i, i + chunkSize);
        chunks.push(chunk);
    }
    return chunks;
}

const CHUNKING_THRESHOLD = 65535;

function applyWithChunking(fn: (...args: number[]) => number, argsArray: number[]): number {
    if (argsArray.length > CHUNKING_THRESHOLD) {
        const chunks: number[][] = splitToChunks(argsArray);
        return fn(...chunks.map(chunk => fn(...chunk)));
    } else {
        return fn(...argsArray);
    }
}

function maxRank(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): number {
    const nodes: string[] = graph.nodes();
    const nodeRanks: number[] = nodes.map(v => {
        const rank: number | undefined = graph.node(v).rank;
        if (rank === undefined) {
            return Number.MIN_VALUE;
        }
        return rank;
    });

    return applyWithChunking(Math.max, nodeRanks);
}

/*
 * Partition a collection into two groups: `lhs` and `rhs`. If the supplied
 * function returns true for an entry it goes into `lhs`. Otherwise it goes
 * into `rhs.
 */
function partition<T>(collection: T[], fn: (value: T) => boolean): PartitionResult<T> {
    const result: PartitionResult<T> = {lhs: [], rhs: []};
    collection.forEach(value => {
        if (fn(value)) {
            result.lhs.push(value);
        } else {
            result.rhs.push(value);
        }
    });
    return result;
}

/*
 * Returns a new function that wraps `fn` with a timer. The wrapper logs the
 * time it takes to execute the function.
 */
function time<T>(name: string, fn: () => T): T {
    const start: number = Date.now();
    try {
        return fn();
    } finally {
        console.log(name + " time: " + (Date.now() - start) + "ms");
    }
}

function notime<T>(name: string, fn: () => T): T {
    return fn();
}

let idCounter = 0;

function uniqueId(prefix: string): string {
    const id: number = ++idCounter;
    return prefix + ("" + id);
}

function range(start: number, limit?: number, step: number = 1): number[] {
    if (limit == null) {
        limit = start;
        start = 0;
    }

    let endCon: (i: number) => boolean = (i) => i < limit!;
    if (step < 0) {
        endCon = (i) => limit! < i;
    }

    const range: number[] = [];
    for (let i = start; endCon(i); i += step) {
        range.push(i);
    }

    return range;
}

function pick<T extends Record<string, unknown>>(source: T, keys: string[]): Partial<T> {
    const dest: Partial<T> = {};
    for (const key of keys) {
        if (source[key] !== undefined) {
            (dest as Record<string, unknown>)[key] = source[key];
        }
    }

    return dest;
}

function mapValues<T, R>(obj: { [key: string]: T }, funcOrProp: ((val: T, key: string) => R) | string): {
    [key: string]: R
} {
    let func: (val: T, key: string) => R;
    if (typeof funcOrProp === 'string') {
        func = (val: T) => (val as Record<string, R>)[funcOrProp] as R;
    } else {
        func = funcOrProp;
    }

    return Object.entries(obj).reduce((acc: { [key: string]: R }, [k, v]) => {
        acc[k] = func(v, k);
        return acc;
    }, {});
}

function zipObject<T>(props: string[], values: T[]): { [key: string]: T } {
    return props.reduce((acc: { [key: string]: T }, key, i) => {
        acc[key] = values[i]!;
        return acc;
    }, {});
}

export const GRAPH_NODE = "\x00";

function compareByOldOrder(oldNodes: NodeCollection, nodeA: NodeLabel, nodeB: NodeLabel) {
    // early return 0 (equal) if any data is missing, or nodes are not edges
    if (!(oldNodes && nodeA && nodeB &&
        nodeA.dummy === "edge" && nodeB.dummy === "edge" &&
        nodeA.edgeObj && nodeB.edgeObj &&
        oldNodes[nodeA.edgeObj.v] && oldNodes[nodeB.edgeObj.v] && oldNodes[nodeA.edgeObj.w] && oldNodes[nodeB.edgeObj.w])) {
        return 0;
    }
    // by default, we assume that we are looking in the forward direction (start -> end)
    let isForward = true;
    // if both edges have the same target, we are in the backwards direction (end -> start)
    // since this comparison is only ever used on a rank immediately after a proper node from which multiple edges emerge
    // that proper node is the common v (source) in the forward direction or the common w (target) in the backwards direction
    if (nodeA.edgeObj.w === nodeB.edgeObj.w) {
        isForward = false;
    }
    const targetRank = isForward? oldNodes[nodeA.edgeObj.v]?.rank ?? NaN + 1 : oldNodes[nodeA.edgeObj.w]?.rank ?? NaN - 1;

    const oldA = Object.entries(oldNodes).find(n => n[1].edgeObj?.v === nodeA.edgeObj!.v && n[1].edgeObj?.w === nodeA.edgeObj!.w && n[1].rank === targetRank);
    const oldB = Object.entries(oldNodes).find(n => n[1].edgeObj?.v === nodeB.edgeObj!.v && n[1].edgeObj?.w === nodeB.edgeObj!.w && n[1].rank === targetRank);
    if (!oldA || !oldB) {
        return 0;
    }
    const oldOrderA = oldA[1].order ?? NaN;
    const oldOrderB = oldB[1].order ?? NaN;
    return isNaN(oldOrderA - oldOrderB) ? 0 : oldOrderA - oldOrderB;
}

/*
 * Simple doubly linked list implementation derived from Cormen, et al.,
 * "Introduction to Algorithms".
 */

interface ListNode {
    _next?: ListNode;
    _prev?: ListNode;

    [key: string]: unknown;
}

class List {
    private _sentinel: ListNode;

    constructor() {
        const sentinel: ListNode = {};
        sentinel._next = sentinel._prev = sentinel;
        this._sentinel = sentinel;
    }

    dequeue(): ListNode | undefined {
        const sentinel = this._sentinel;
        const entry = sentinel._prev;
        if (entry !== sentinel) {
            unlink(entry!);
            return entry;
        }
        return undefined;
    }

    enqueue(entry: ListNode): void {
        const sentinel = this._sentinel;
        if (entry._prev && entry._next) {
            unlink(entry);
        }
        entry._next = sentinel._next;
        sentinel._next!._prev = entry;
        sentinel._next = entry;
        entry._prev = sentinel;
    }

    toString(): string {
        const strs: string[] = [];
        const sentinel = this._sentinel;
        let curr = sentinel._prev;
        while (curr !== sentinel) {
            strs.push(JSON.stringify(curr, filterOutLinks));
            curr = curr!._prev;
        }
        return "[" + strs.join(", ") + "]";
    }
}

function unlink(entry: ListNode): void {
    entry._prev!._next = entry._next;
    entry._next!._prev = entry._prev;
    delete entry._next;
    delete entry._prev;
}

function filterOutLinks(k: string, v: unknown): unknown {
    if (k !== "_next" && k !== "_prev") {
        return v;
    }
    return undefined;
}

export default List;

import {Graph} from "./graph-lib";
import List from './data/list';
import type {Edge, WeightFunction} from './types';

/*
 * A greedy heuristic for finding a feedback arc set for a graph. A feedback
 * arc set is a set of edges that can be removed to make a graph acyclic.
 * The algorithm comes from: P. Eades, X. Lin, and W. F. Smyth, "A fast and
 * effective heuristic for the feedback arc set problem." This implementation
 * adjusts that from the paper to allow for weighted edges.
 */

const DEFAULT_WEIGHT_FN: WeightFunction = () => 1;

interface FASEntry {
    v: string;
    in: number;
    out: number;
    [key: string]: unknown;
}

interface FASState {
    graph: Graph;
    buckets: List[];
    zeroIdx: number;
}

export default function greedyFAS(graph: Graph, weightFn?: WeightFunction): Edge[] {
    if (graph.nodeCount() <= 1) {
        return [];
    }
    const state = buildState(graph, weightFn || DEFAULT_WEIGHT_FN);
    const results = doGreedyFAS(state.graph, state.buckets, state.zeroIdx);

    // Expand multi-edges
    return results.flatMap(edge => graph.outEdges(edge.v, edge.w) || []);
}

function doGreedyFAS(g: Graph, buckets: List[], zeroIdx: number): Edge[] {
    let results: Edge[] = [];
    const sources = buckets[buckets.length - 1]!;
    const sinks = buckets[0]!;

    let entry: FASEntry | undefined;
    while (g.nodeCount()) {
        while ((entry = sinks.dequeue() as FASEntry | undefined)) {
            removeNode(g, buckets, zeroIdx, entry);
        }
        while ((entry = sources.dequeue() as FASEntry | undefined)) {
            removeNode(g, buckets, zeroIdx, entry);
        }
        if (g.nodeCount()) {
            for (let i = buckets.length - 2; i > 0; --i) {
                entry = buckets[i]?.dequeue() as FASEntry | undefined;
                if (entry) {
                    results = results.concat(removeNode(g, buckets, zeroIdx, entry, true) || []);
                    break;
                }
            }
        }
    }

    return results;
}

function removeNode(
    graph: Graph,
    buckets: List[],
    zeroIdx: number,
    entry: FASEntry,
    collectPredecessors?: boolean
): Edge[] | undefined {
    const collected: Edge[] = [];
    const results: Edge[] | undefined = collectPredecessors ? collected : undefined;

    (graph.inEdges(entry.v) || []).forEach(edge => {
        const weight = graph.edge(edge) as number;
        const uEntry = graph.node(edge.v) as FASEntry;

        if (collectPredecessors) {
            collected.push({v: edge.v, w: edge.w});
        }

        uEntry.out -= weight;
        assignBucket(buckets, zeroIdx, uEntry);
    });

    (graph.outEdges(entry.v) || []).forEach(edge => {
        const weight = graph.edge(edge) as number;
        const w = edge.w;
        const wEntry = graph.node(w) as FASEntry;
        wEntry.in -= weight;
        assignBucket(buckets, zeroIdx, wEntry);
    });

    graph.removeNode(entry.v);

    return results;
}

function buildState(graph: Graph, weightFn: WeightFunction): FASState {
    const fasGraph = new Graph();
    let maxIn = 0;
    let maxOut = 0;

    graph.nodes().forEach(v => {
        fasGraph.setNode(v, {v: v, in: 0, out: 0});
    });

    // Aggregate weights on nodes, but also sum the weights across multi-edges
    // into a single edge for the fasGraph.
    graph.edges().forEach(edge => {
        const prevWeight = (fasGraph.edge(edge.v, edge.w) as number) || 0;
        const weight = weightFn(edge);
        const edgeWeight = prevWeight + weight;
        fasGraph.setEdge(edge.v, edge.w, edgeWeight);
        const vNode = fasGraph.node(edge.v) as FASEntry;
        const wNode = fasGraph.node(edge.w) as FASEntry;
        maxOut = Math.max(maxOut, vNode.out += weight);
        maxIn = Math.max(maxIn, wNode.in += weight);
    });

    const buckets = range(maxOut + maxIn + 3).map(() => new List());
    const zeroIdx = maxIn + 1;

    fasGraph.nodes().forEach(v => {
        assignBucket(buckets, zeroIdx, fasGraph.node(v) as FASEntry);
    });

    return {graph: fasGraph, buckets: buckets, zeroIdx: zeroIdx};
}

function assignBucket(buckets: List[], zeroIdx: number, entry: FASEntry): void {
    if (!entry.out) {
        buckets[0]?.enqueue(entry);
    } else if (!entry.in) {
        buckets[buckets.length - 1]?.enqueue(entry);
    } else {
        buckets[entry.out - entry.in + zeroIdx]?.enqueue(entry);
    }
}

function range(limit: number): number[] {
    const range: number[] = [];
    for (let i = 0; i < limit; i++) {
        range.push(i);
    }

    return range;
}

import {Graph} from "./graph-lib";
import greedyFAS from "./greedy-fas";
import {uniqueId} from "./util";
import type {Edge, EdgeLabel, GraphLabel, NodeLabel, WeightFunction} from "./types";

export {run, undo};

function run(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, oldGraph?: Graph | null): void {
    const fas = (graph.graph().acyclicer === "greedy"
        ? greedyFAS(graph, weightFn(graph))
        : dfsFAS(graph, oldGraph ?? null));
    fas.forEach(e => {
        const label = graph.edge(e)!;
        graph.removeEdge(e);
        label.forwardName = e.name;
        label.reversed = true;
        graph.setEdge(e.w, e.v, label, uniqueId("rev"));
    });

    function weightFn(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): WeightFunction {
        return (e: Edge) => {
            return g.edge(e)!.weight!;
        };
    }
}

function dfsFAS(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, oldGraph: Graph|null): Edge[] {
    const fas: Edge[] = [];
    const stack: { [key: string]: boolean } = {};
    const visited: { [key: string]: boolean } = {};

    function dfs(v: string): void {
        if (Object.hasOwn(visited, v)) {
            return;
        }
        visited[v] = true;
        stack[v] = true;
        graph.outEdges(v)!.forEach(e => {
            if (Object.hasOwn(stack, e.w)) {
                fas.push(e);
            } else {
                dfs(e.w);
            }
        });
        delete stack[v];
    }

    function dfsDynamic(v: string) {
        if (Object.hasOwn(visited, v)) {
            return;
        }
        visited[v] = true;
        stack[v] = true;
        graph.outEdges(v)?.forEach(e => {
            if (Object.hasOwn(stack, e.w) ||
                (oldGraph!.node(v)?.rank > oldGraph!.node(e.w)?.rank) && isReachedFromStartWithoutEdge(graph, e.w, e)) {
                fas.push(e);
            } else {
                dfsDynamic(e.w);
            }
        });
        delete stack[v];
    }

    let dfsFn = dfs;
    if (oldGraph && typeof oldGraph.node === 'function') {
        dfsFn = dfsDynamic;
    }

    graph.sources().forEach(dfsFn);
    graph.nodes().forEach(dfsFn);

    return fas;
}

function undo(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    graph.edges().forEach(e => {
        const label = graph.edge(e)!;
        if (label.reversed) {
            graph.removeEdge(e);

            const forwardName = label.forwardName;
            delete label.reversed;
            delete label.forwardName;
            graph.setEdge(e.w, e.v, label, forwardName);
        }
    });
}

function isReachedFromStartWithoutEdge(graph: Graph, node: string, ignoreEdge: Edge) {
    // reverse dfs from the given node to 'Start' without using edge e
    const localVisited = new Set<string>();

    function reverseDfs(v: string): boolean {
        if (graph.sources().includes(v)) {
            return true;
        }
        localVisited.add(v);
        for (const e of graph.inEdges(v) ?? []) {
            // do not use ignored edge
            // do not visit the same node twice
            if (!(e.v === ignoreEdge.v && e.w === ignoreEdge.w)
                && !localVisited.has(e.v)) {
                if (reverseDfs(e.v)) {
                    return true;
                }
            }
        }
        return false;
    }
    return reverseDfs(node);
}

import {addDummyNode} from "./util";
import type {Edge, EdgeLabel, Graph, GraphLabel, NodeLabel} from "./types";

export {
    run,
    undo
};

/*
 * Breaks any long edges in the graph into short segments that span 1 layer
 * each. This operation is undoable with the denormalize function.
 *
 * Pre-conditions:
 *
 *    1. The input graph is a DAG.
 *    2. Each node in the graph has a "rank" property.
 *
 * Post-condition:
 *
 *    1. All edges in the graph have a length of 1.
 *    2. Dummy nodes are added where edges have been split into segments.
 *    3. The graph is augmented with a "dummyChains" attribute which contains
 *       the first dummy in each chain of dummy nodes produced.
 */
function run(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    graph.graph().dummyChains = [];
    graph.edges().forEach(edge => normalizeEdge(graph, edge));
}

function normalizeEdge(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, e: Edge): void {
    let v: string = e.v;
    let vRank: number = graph.node(v).rank!;
    const w: string = e.w;
    const wRank: number = graph.node(w).rank!;
    const name: string | undefined = e.name;
    const edgeLabel: EdgeLabel = graph.edge(e);
    const labelRank: number | undefined = edgeLabel.labelRank;

    if (wRank === vRank + 1) return;

    graph.removeEdge(e);

    let dummy: string;
    let attrs: Partial<NodeLabel>;
    let i: number;
    for (i = 0, ++vRank; vRank < wRank; ++i, ++vRank) {
        edgeLabel.points = [];
        attrs = {
            width: 0,
            height: 0,
            edgeLabel: edgeLabel,
            edgeObj: e,
            rank: vRank
        };
        dummy = addDummyNode(graph, "edge", attrs, "_d");
        if (vRank === labelRank) {
            attrs.width = edgeLabel.width;
            attrs.height = edgeLabel.height;
            attrs.dummy = "edge-label";
            attrs.labelpos = edgeLabel.labelpos;
        }
        graph.setEdge(v, dummy, {weight: edgeLabel.weight}, name);
        if (i === 0) {
            graph.graph().dummyChains!.push(dummy);
        }
        v = dummy;
    }

    graph.setEdge(v, w, {weight: edgeLabel.weight}, name);
}

function undo(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    graph.graph().dummyChains!.forEach(v => {
        let node: NodeLabel = graph.node(v);
        const origLabel: EdgeLabel = node.edgeLabel!;
        let w: string;
        graph.setEdge(node.edgeObj!, origLabel);
        while (node.dummy) {
            w = graph.successors(v)![0]!;
            graph.removeNode(v);
            origLabel.points!.push({x: node.x!, y: node.y!});
            if (node.dummy === "edge-label") {
                origLabel.x = node.x;
                origLabel.y = node.y;
                origLabel.width = node.width;
                origLabel.height = node.height;
            }
            v = w;
            node = graph.node(v);
        }
    });
}

import {applyWithChunking} from "../util";
import type {Edge, EdgeLabel, Graph, GraphLabel, NodeLabel} from "../types";

export {longestPath, slack};

/*
 * Initializes ranks for the input graph using the longest path algorithm. This
 * algorithm scales well and is fast in practice, it yields rather poor
 * solutions. Nodes are pushed to the lowest layer possible, leaving the bottom
 * ranks wide and leaving edges longer than necessary. However, due to its
 * speed, this algorithm is good for getting an initial ranking that can be fed
 * into other algorithms.
 *
 * This algorithm does not normalize layers because it will be used by other
 * algorithms in most cases. If using this algorithm directly, be sure to
 * run normalize at the end.
 *
 * Pre-conditions:
 *
 *    1. Input graph is a DAG.
 *    2. Input graph node labels can be assigned properties.
 *
 * Post-conditions:
 *
 *    1. Each node will be assign an (unnormalized) "rank" property.
 */
function longestPath(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const visited: { [key: string]: boolean } = {};

    function dfs(v: string): number {
        const label: NodeLabel = graph.node(v);
        if (Object.hasOwn(visited, v)) {
            return label.rank!;
        }
        visited[v] = true;

        const outEdges = graph.outEdges(v);
        const outEdgesMinLens: number[] = outEdges ? outEdges.map(e => {
            if (e == null) {
                return Number.POSITIVE_INFINITY;
            }

            return dfs(e.w) - graph.edge(e).minlen!;
        }) : [];

        let rank: number = applyWithChunking(Math.min, outEdgesMinLens);

        if (rank === Number.POSITIVE_INFINITY) {
            rank = 0;
        }

        return (label.rank = rank);
    }

    graph.sources().forEach(dfs);
}

/*
 * Returns the amount of slack for the given edge. The slack is defined as the
 * difference between the length of the edge and its minimum length.
 */
function slack(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, edge: Edge): number {
    return graph.node(edge.w).rank! - graph.node(edge.v).rank! - graph.edge(edge).minlen!;
}

import {Graph} from "../graph-lib";
import {slack} from "./util";
import type {Edge, EdgeLabel, GraphLabel, NodeLabel} from "../types";

// Internal type for tree node labels
interface TreeNodeLabel {
    low?: number;
    lim?: number;
    parent?: string;
}

// Internal type for tree edge labels
interface TreeEdgeLabel {
    cutvalue?: number;
}

export default feasibleTree;
export type {TreeNodeLabel, TreeEdgeLabel};

/*
 * Constructs a spanning tree with tight edges and adjusted the input node's
 * ranks to achieve this. A tight edge is one that is has a length that matches
 * its "minlen" attribute.
 *
 * The basic structure for this function is derived from Gansner, et al., "A
 * Technique for Drawing Directed Graphs."
 *
 * Pre-conditions:
 *
 *    1. Graph must be a DAG.
 *    2. Graph must be connected.
 *    3. Graph must have at least one node.
 *    5. Graph nodes must have been previously assigned a "rank" property that
 *       respects the "minlen" property of incident edges.
 *    6. Graph edges must have a "minlen" property.
 *
 * Post-conditions:
 *
 *    - Graph nodes will have their rank adjusted to ensure that all edges are
 *      tight.
 *
 * Returns a tree (undirected graph) that is constructed using only "tight"
 * edges.
 */
function feasibleTree(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): Graph<object, TreeNodeLabel, TreeEdgeLabel> {
    const tree = new Graph<object, TreeNodeLabel, TreeEdgeLabel>({directed: false});

    // Choose arbitrary node from which to start our tree
    const nodes = graph.nodes();
    if (nodes.length === 0) {
        throw new Error("Graph must have at least one node");
    }
    const start: string = nodes[0]!;
    const size: number = graph.nodeCount();
    tree.setNode(start, {});

    let edge: Edge | null;
    let delta: number;
    while (tightTree(tree, graph) < size) {
        edge = findMinSlackEdge(tree, graph);
        if (!edge) break;
        delta = tree.hasNode(edge.v) ? slack(graph, edge) : -slack(graph, edge);
        shiftRanks(tree, graph, delta);
    }

    return tree;
}

/*
 * Finds a maximal tree of tight edges and returns the number of nodes in the
 * tree.
 */
function tightTree(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): number {
    function dfs(v: string): void {
        const nodeEdges = graph.nodeEdges(v);
        if (nodeEdges) {
            nodeEdges.forEach(e => {
                const edgeV: string = e.v;
                const w: string = (v === edgeV) ? e.w : edgeV;
                if (!tree.hasNode(w) && !slack(graph, e)) {
                    tree.setNode(w, {});
                    tree.setEdge(v, w, {});
                    dfs(w);
                }
            });
        }
    }

    tree.nodes().forEach(dfs);
    return tree.nodeCount();
}

/*
 * Finds the edge with the smallest slack that is incident on tree and returns
 * it.
 */
function findMinSlackEdge(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): Edge | null {
    const edges: Edge[] = graph.edges();

    return edges.reduce((acc: [number, Edge | null], edge: Edge): [number, Edge | null] => {
        let edgeSlack: number = Number.POSITIVE_INFINITY;
        if (tree.hasNode(edge.v) !== tree.hasNode(edge.w)) {
            edgeSlack = slack(graph, edge);
        }

        if (edgeSlack < acc[0]) {
            return [edgeSlack, edge];
        }

        return acc;
    }, [Number.POSITIVE_INFINITY, null])[1];
}

function shiftRanks(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, delta: number): void {
    tree.nodes().forEach(v => graph.node(v).rank! += delta);
}

import feasibleTree, {type TreeEdgeLabel, type TreeNodeLabel} from "./feasible-tree";
import {longestPath as initRank, slack} from "./util";
import {alg} from "../graph-lib";
import {simplify} from "../util";
import type {Edge, EdgeLabel, Graph, GraphLabel, NodeLabel} from "../types";

const {preorder, postorder} = alg;

export default networkSimplex;

// Expose some internals for testing purposes
networkSimplex.initLowLimValues = initLowLimValues;
networkSimplex.initCutValues = initCutValues;
networkSimplex.calcCutValue = calcCutValue;
networkSimplex.leaveEdge = leaveEdge;
networkSimplex.enterEdge = enterEdge;
networkSimplex.exchangeEdges = exchangeEdges;

/*
 * The network simplex algorithm assigns ranks to each node in the input graph
 * and iteratively improves the ranking to reduce the length of edges.
 *
 * Preconditions:
 *
 *    1. The input graph must be a DAG.
 *    2. All nodes in the graph must have an object value.
 *    3. All edges in the graph must have "minlen" and "weight" attributes.
 *
 * Postconditions:
 *
 *    1. All nodes in the graph will have an assigned "rank" attribute that has
 *       been optimized by the network simplex algorithm. Ranks start at 0.
 *
 *
 * A rough sketch of the algorithm is as follows:
 *
 *    1. Assign initial ranks to each node. We use the longest path algorithm,
 *       which assigns ranks to the lowest position possible. In general this
 *       leads to very wide bottom ranks and unnecessarily long edges.
 *    2. Construct a feasible tight tree. A tight tree is one such that all
 *       edges in the tree have no slack (difference between length of edge
 *       and minlen for the edge). This by itself greatly improves the assigned
 *       rankings by shorting edges.
 *    3. Iteratively find edges that have negative cut values. Generally a
 *       negative cut value indicates that the edge could be removed and a new
 *       tree edge could be added to produce a more compact graph.
 *
 * Much of the algorithms here are derived from Gansner, et al., "A Technique
 * for Drawing Directed Graphs." The structure of the file roughly follows the
 * structure of the overall algorithm.
 */
function networkSimplex(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    graph = simplify(graph as Graph<GraphLabel, NodeLabel, EdgeLabel>) as Graph<GraphLabel, NodeLabel, EdgeLabel>;
    initRank(graph);

    const t = feasibleTree(graph);
    initLowLimValues(t);
    initCutValues(t, graph);

    let e: Edge | undefined;
    let f: Edge;
    while ((e = leaveEdge(t))) {
        f = enterEdge(t, graph, e);
        exchangeEdges(t, graph, e, f);
    }
}

/*
 * Initializes cut values for all edges in the tree.
 */
function initCutValues(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    let visitedNodes: string[] = postorder(tree, tree.nodes());
    visitedNodes = visitedNodes.slice(0, visitedNodes.length - 1);
    visitedNodes.forEach(v => assignCutValue(tree, graph, v));
}

function assignCutValue(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, child: string): void {
    const childLab: TreeNodeLabel = tree.node(child);
    const parent: string = childLab.parent!;
    const edge = tree.edge(child, parent);
    edge.cutvalue = calcCutValue(tree, graph, child);
}

/*
 * Given the tight tree, its graph, and a child in the graph calculate and
 * return the cut value for the edge between the child and its parent.
 */
function calcCutValue(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, child: string): number {
    const childLab: TreeNodeLabel = tree.node(child);
    const parent: string = childLab.parent!;
    // True if the child is on the tail end of the edge in the directed graph
    let childIsTail: boolean = true;
    // The graph's view of the tree edge we're inspecting
    let graphEdge: EdgeLabel | undefined = graph.edge(child, parent);
    // The accumulated cut value for the edge between this node and its parent
    let cutValue: number = 0;

    if (!graphEdge) {
        childIsTail = false;
        graphEdge = graph.edge(parent, child);
    }

    cutValue = graphEdge.weight!;

    const nodeEdges = graph.nodeEdges(child);
    if (nodeEdges) {
        nodeEdges.forEach(edge => {
            const isOutEdge: boolean = edge.v === child;
            const other: string = isOutEdge ? edge.w : edge.v;

            if (other !== parent) {
                const pointsToHead: boolean = isOutEdge === childIsTail;
                const otherWeight: number = graph.edge(edge).weight!;

                cutValue += pointsToHead ? otherWeight : -otherWeight;
                if (isTreeEdge(tree, child, other)) {
                    const treeEdge = tree.edge(child, other);
                    const otherCutValue: number = treeEdge.cutvalue!;
                    cutValue += pointsToHead ? -otherCutValue : otherCutValue;
                }
            }
        });
    }

    return cutValue;
}

function initLowLimValues(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, root?: string): void {
    if (arguments.length < 2) {
        root = tree.nodes()[0];
    }
    dfsAssignLowLim(tree, {}, 1, root!);
}

function dfsAssignLowLim(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, visited: {
    [key: string]: boolean
}, nextLim: number, v: string, parent?: string): number {
    const low: number = nextLim;
    const label: TreeNodeLabel = tree.node(v);

    visited[v] = true;
    const neighbors = tree.neighbors(v);
    if (neighbors) {
        neighbors.forEach(w => {
            if (!Object.hasOwn(visited, w)) {
                nextLim = dfsAssignLowLim(tree, visited, nextLim, w, v);
            }
        });
    }

    label.low = low;
    label.lim = nextLim++;
    if (parent) {
        label.parent = parent;
    } else {
        // TODO should be able to remove this when we incrementally update low lim
        delete label.parent;
    }

    return nextLim;
}

function leaveEdge(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>): Edge | undefined {
    return tree.edges().find(e => {
        const edge = tree.edge(e);
        return edge.cutvalue! < 0;
    });
}

function enterEdge(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, edge: Edge): Edge {
    let v: string = edge.v;
    let w: string = edge.w;

    // For the rest of this function we assume that v is the tail and w is the
    // head, so if we don't have this edge in the graph we should flip it to
    // match the correct orientation.
    if (!graph.hasEdge(v, w)) {
        v = edge.w;
        w = edge.v;
    }

    const vLabel: TreeNodeLabel = tree.node(v);
    const wLabel: TreeNodeLabel = tree.node(w);
    let tailLabel: TreeNodeLabel = vLabel;
    let flip: boolean = false;

    // If the root is in the tail of the edge then we need to flip the logic that
    // checks for the head and tail nodes in the candidates function below.
    if (vLabel.lim! > wLabel.lim!) {
        tailLabel = wLabel;
        flip = true;
    }

    const candidates: Edge[] = graph.edges().filter(edge => {
        return flip === isDescendant(tree, tree.node(edge.v), tailLabel) &&
            flip !== isDescendant(tree, tree.node(edge.w), tailLabel);
    });

    return candidates.reduce((acc: Edge, edge: Edge): Edge => {
        if (slack(graph, edge) < slack(graph, acc)) {
            return edge;
        }

        return acc;
    });
}

function exchangeEdges(t: Graph<object, TreeNodeLabel, TreeEdgeLabel>, g: Graph<GraphLabel, NodeLabel, EdgeLabel>, e: Edge, f: Edge): void {
    const v: string = e.v;
    const w: string = e.w;
    t.removeEdge(v, w);
    t.setEdge(f.v, f.w, {});
    initLowLimValues(t);
    initCutValues(t, g);
    updateRanks(t, g);
}

function updateRanks(t: Graph<object, TreeNodeLabel, TreeEdgeLabel>, g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const root: string | undefined = t.nodes().find(v => {
        const node = t.node(v);
        return !node.parent;
    });
    if (!root) return;

    let vs: string[] = preorder(t, [root]);
    vs = vs.slice(1);
    vs.forEach(v => {
        const treeNode = t.node(v);
        const parent: string = treeNode.parent!;
        let edge: EdgeLabel | undefined = g.edge(v, parent);
        let flipped: boolean = false;

        if (!edge) {
            edge = g.edge(parent, v);
            flipped = true;
        }

        g.node(v).rank = g.node(parent).rank! + (flipped ? edge!.minlen! : -edge!.minlen!);
    });
}

/*
 * Returns true if the edge is in the tree.
 */
function isTreeEdge(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, u: string, v: string): boolean {
    return tree.hasEdge(u, v);
}

/*
 * Returns true if the specified node is descendant of the root node per the
 * assigned low and lim attributes in the tree.
 */
function isDescendant(tree: Graph<object, TreeNodeLabel, TreeEdgeLabel>, vLabel: TreeNodeLabel, rootLabel: TreeNodeLabel): boolean {
    return rootLabel.low! <= vLabel.lim! && vLabel.lim! <= rootLabel.lim!;
}

