import {Graph} from './graph';
import type {GraphOptions, Label} from './types';

interface JsonGraph {
    options: GraphOptions;
    nodes: JsonNode[];
    edges: JsonEdge[];
    value?: unknown;
}

interface JsonNode {
    v: string;
    value?: unknown;
    parent?: string;
}

interface JsonEdge {
    v: string;
    w: string;
    name?: string;
    value?: unknown;
}

/**
 * Creates a JSON representation of the graph that can be serialized to a string with
 * JSON.stringify. The graph can later be restored using json.read.
 *
 * @param graph - target to create JSON representation of.
 * @returns JSON serializable graph representation
 */
export function write(graph: Graph): JsonGraph {
    const json: JsonGraph = {
        options: {
            directed: graph.isDirected(),
            multigraph: graph.isMultigraph(),
            compound: graph.isCompound()
        },
        nodes: writeNodes(graph),
        edges: writeEdges(graph)
    };

    const graphLabel = graph.graph();
    if (graphLabel !== undefined) {
        json.value = structuredClone(graphLabel);
    }

    return json;
}

function writeNodes(g: Graph): JsonNode[] {
    return g.nodes().map(v => {
        const nodeValue = g.node(v);
        const parent = g.parent(v);
        const node: JsonNode = {v};

        if (nodeValue !== undefined) {
            node.value = nodeValue;
        }
        if (parent !== undefined) {
            node.parent = parent;
        }

        return node;
    });
}

function writeEdges(g: Graph): JsonEdge[] {
    return g.edges().map(e => {
        const edgeValue = g.edge(e);
        const edge: JsonEdge = {v: e.v, w: e.w};

        if (e.name !== undefined) {
            edge.name = e.name;
        }
        if (edgeValue !== undefined) {
            edge.value = edgeValue;
        }

        return edge;
    });
}

/**
 * Takes JSON as input and returns the graph representation.
 *
 * @param json - JSON serializable graph representation
 * @returns graph constructed according to specified representation
 *
 * @example
 * var g2 = graphlib.json.read(JSON.parse(str));
 * g2.nodes();
 * // ['a', 'b']
 * g2.edges()
 * // [ { v: 'a', w: 'b' } ]
 */
export function read<GraphLabel = Label, NodeLabel = Label, EdgeLabel = Label>(
    json: JsonGraph
): Graph<GraphLabel, NodeLabel, EdgeLabel> {
    const g = new Graph<GraphLabel, NodeLabel, EdgeLabel>(json.options);

    if (json.value !== undefined) {
        g.setGraph(json.value as GraphLabel);
    }

    json.nodes.forEach(entry => {
        g.setNode(entry.v, entry.value as NodeLabel);
        if (entry.parent) {
            g.setParent(entry.v, entry.parent);
        }
    });

    json.edges.forEach(entry => {
        g.setEdge({v: entry.v, w: entry.w, name: entry.name}, entry.value as EdgeLabel);
    });

    return g;
}

﻿// Use LayoutContext and coordinate-system transforms for all node ranking
// This will ensure correct ranking for per-cluster direction
import {longestPath} from "./util";
import feasibleTree from "./feasible-tree";
import networkSimplex from "./network-simplex";
import type {EdgeLabel, Graph, GraphLabel, NodeLabel, RankerFunction} from "../types";

export default rank;

/*
 * Assigns a rank to each node in the input graph that respects the "minlen"
 * constraint specified on edges between nodes.
 *
 * This basic structure is derived from Gansner, et al., "A Technique for
 * Drawing Directed Graphs."
 *
 * Pre-conditions:
 *
 *    1. Graph must be a connected DAG
 *    2. Graph nodes must be objects
 *    3. Graph edges must have "weight" and "minlen" attributes
 *
 * Post-conditions:
 *
 *    1. Graph nodes will have a "rank" attribute based on the results of the
 *       algorithm. Ranks can start at any index (including negative), we'll
 *       fix them up later.
 */
function rank(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const ranker: RankerFunction | string | undefined = graph.graph().ranker;
    if (typeof ranker === 'function') {
        return (ranker as RankerFunction)(graph);
    }
    switch (ranker) {
    case "network-simplex":
        networkSimplexRanker(graph);
        break;
    case "tight-tree":
        tightTreeRanker(graph);
        break;
    case "longest-path":
        longestPathRanker(graph);
        break;
    case "none":
        break;
    default:
        networkSimplexRanker(graph);
    }
}

// A fast and simple ranker, but results are far from optimal.
const longestPathRanker: RankerFunction = longestPath;

function tightTreeRanker(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    longestPath(g);
    feasibleTree(g);
}

function networkSimplexRanker(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    networkSimplex(g);
}

import type {Edge, EdgeLabel, Graph, GraphLabel, NodeLabel} from "./types";
import {GRAPH_NODE} from "./util";

export default parentDummyChains;

interface PostorderNum {
    low: number;
    lim: number;
}

interface PathData {
    path: (string | undefined)[];
    lca: string | undefined;
}

function parentDummyChains(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const postorderNums: { [key: string]: PostorderNum } = postorder(graph);
    const graphData = graph.graph();
    if (!Array.isArray(graphData.dummyChains)) return;
    const dummyChains = graphData.dummyChains;
    dummyChains.forEach(v => {
        let node: NodeLabel = graph.node(v);
        const edgeObj: Edge = node.edgeObj!;
        const pathData: PathData = findPath(graph, postorderNums, edgeObj.v, edgeObj.w);
        const path: (string | undefined)[] = pathData.path;
        const lca: string | undefined = pathData.lca;
        let pathIdx: number = 0;
        let pathV: string | undefined = path[pathIdx];
        let ascending: boolean = true;

        while (v !== edgeObj.w) {
            node = graph.node(v);

            if (ascending) {
                while ((pathV = path[pathIdx]) !== lca &&
                graph.node(pathV!).maxRank! < node.rank!) {
                    pathIdx++;
                }

                if (pathV === lca) {
                    ascending = false;
                }
            }

            if (!ascending) {
                while (pathIdx < path.length - 1 &&
                graph.node((path[pathIdx + 1])!).minRank! <= node.rank!) {
                    pathIdx++;
                }
                pathV = path[pathIdx];
            }

            if (pathV !== undefined) {
                graph.setParent(v, pathV);
            }
            v = graph.successors(v)![0]!;
        }
    });
}

// Find a path from v to w through the lowest common ancestor (LCA). Return the
// full path and the LCA.
function findPath(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    postorderNums: { [key: string]: PostorderNum },
    v: string,
    w: string
): PathData {
    const vPath: (string | undefined)[] = [];
    const wPath: (string | undefined)[] = [];
    const low: number = Math.min(postorderNums[v]!.low, postorderNums[w]!.low);
    const lim: number = Math.max(postorderNums[v]!.lim, postorderNums[w]!.lim);
    let parent: string | undefined;

    // Traverse up from v to find the LCA
    parent = v;
    do {
        parent = graph.parent(parent) as string | undefined;
        vPath.push(parent);
    } while (parent &&
    (postorderNums[parent]!.low > low || lim > postorderNums[parent]!.lim));
    const lca = parent;

    // Traverse from w to LCA
    let wParent: string = w;
    while ((wParent = graph.parent(wParent) as string) !== lca) {
        wPath.push(wParent);
    }

    return {path: vPath.concat(wPath.reverse()), lca: lca};
}

function postorder(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): { [key: string]: PostorderNum } {
    const result: { [key: string]: PostorderNum } = {};
    let lim: number = 0;

    function dfs(v: string): void {
        const low: number = lim;
        graph.children(v).forEach(dfs);
        result[v] = {low: low, lim: lim++};
    }

    graph.children(GRAPH_NODE).forEach(dfs);

    return result;
}

import {addBorderNode, addDummyNode, applyWithChunking, GRAPH_NODE} from "./util";
import type {EdgeLabel, Graph, GraphLabel, NodeLabel} from "./types";

export {
    run,
    cleanup,
};

/*
 * A nesting graph creates dummy nodes for the tops and bottoms of subgraphs,
 * adds appropriate edges to ensure that all cluster nodes are placed between
 * these boundaries, and ensures that the graph is connected.
 *
 * In addition we ensure, through the use of the minlen property, that nodes
 * and subgraph border nodes to not end up on the same rank.
 *
 * Preconditions:
 *
 *    1. Input graph is a DAG
 *    2. Nodes in the input graph has a minlen attribute
 *
 * Postconditions:
 *
 *    1. Input graph is connected.
 *    2. Dummy nodes are added for the tops and bottoms of subgraphs.
 *    3. The minlen attribute for nodes is adjusted to ensure nodes do not
 *       get placed on the same rank as subgraph border nodes.
 *
 * The nesting graph idea comes from Sander, "Layout of Compound Directed
 * Graphs."
 */
function run(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const root: string = addDummyNode(graph, "root", {}, "_root");
    const depths: { [key: string]: number } = treeDepths(graph);
    const depthsArr: number[] = Object.values(depths);
    const height: number = applyWithChunking(Math.max, depthsArr) - 1; // Note: depths is an Object not an array
    const nodeSep: number = 2 * height + 1;

    graph.graph().nestingRoot = root;

    // Multiply minlen by nodeSep to align nodes on non-border ranks.
    graph.edges().forEach(e => graph.edge(e).minlen! *= nodeSep);

    // Calculate a weight that is sufficient to keep subgraphs vertically compact
    const weight: number = sumWeights(graph) + 1;

    // Create border nodes and link them up
    graph.children(GRAPH_NODE).forEach(child => {
        dfs(graph, root, nodeSep, weight, height, depths, child);
    });

    // Save the multiplier for node layers for later removal of empty border
    // layers.
    graph.graph().nodeRankFactor = nodeSep;
}

function dfs(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    root: string,
    nodeSep: number,
    weight: number,
    height: number,
    depths: { [key: string]: number },
    v: string
): void {
    const children: string[] = graph.children(v);
    if (!children.length) {
        if (v !== root) {
            graph.setEdge(root, v, {weight: 0, minlen: nodeSep});
        }
        return;
    }

    const top: string = addBorderNode(graph, "_bt");
    const bottom: string = addBorderNode(graph, "_bb");
    const label: NodeLabel = graph.node(v);

    graph.setParent(top, v);
    label.borderTop = top;
    graph.setParent(bottom, v);
    label.borderBottom = bottom;

    children.forEach(child => {
        dfs(graph, root, nodeSep, weight, height, depths, child);

        const childNode: NodeLabel = graph.node(child);
        const childTop: string = childNode.borderTop ? childNode.borderTop : child;
        const childBottom: string = childNode.borderBottom ? childNode.borderBottom : child;
        const thisWeight: number = childNode.borderTop ? weight : 2 * weight;
        const minlen: number = childTop !== childBottom ? 1 : height - (depths[v] ?? 0) + 1;

        graph.setEdge(top, childTop, {
            weight: thisWeight,
            minlen: minlen,
            nestingEdge: true
        });

        graph.setEdge(childBottom, bottom, {
            weight: thisWeight,
            minlen: minlen,
            nestingEdge: true
        });
    });

    if (!graph.parent(v)) {
        graph.setEdge(root, top, {weight: 0, minlen: height + (depths[v] ?? 0)});
    }
}

function treeDepths(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): { [key: string]: number } {
    const depths: { [key: string]: number } = {};

    function dfs(v: string, depth: number): void {
        const children: string[] = graph.children(v);
        if (children && children.length) {
            children.forEach(child => dfs(child, depth + 1));
        }
        depths[v] = depth;
    }

    graph.children(GRAPH_NODE).forEach(v => dfs(v, 1));
    return depths;
}

function sumWeights(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): number {
    return graph.edges().reduce((acc, e) => acc + graph.edge(e).weight!, 0);
}

function cleanup(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const graphLabel: GraphLabel = graph.graph();
    graph.removeNode(graphLabel.nestingRoot!);
    delete graphLabel.nestingRoot;
    graph.edges().forEach(e => {
        const edge: EdgeLabel = graph.edge(e);
        if (edge.nestingEdge) {
            graph.removeEdge(e);
        }
    });
}

import {addDummyNode, GRAPH_NODE} from "./util";
import type {EdgeLabel, Graph, GraphLabel, NodeLabel} from "./types";

export default addBorderSegments;

function addBorderSegments(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    // Use LayoutContext and coordinate-system transforms for all border segment placement
    // This will ensure correct placement for per-cluster direction
    function dfs(v: string): void {
        const children: string[] = graph.children(v);
        const node = graph.node(v);
        if (children.length) {
            children.forEach(dfs);
        }

        if (node && Object.hasOwn(node, "minRank")) {
            node.borderLeft = [];
            node.borderRight = [];
            for (let rank: number = node.minRank!, maxRank: number = node.maxRank! + 1;
                rank < maxRank;
                ++rank) {
                addBorderNode(graph, "borderLeft", "_bl", v, node, rank);
                addBorderNode(graph, "borderRight", "_br", v, node, rank);
            }
        }
    }

    graph.children(GRAPH_NODE).forEach(dfs);
}

function addBorderNode(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    prop: "borderLeft" | "borderRight",
    prefix: string,
    sg: string,
    sgNode: EdgeLabel,
    rank: number
): void {
    const label: Partial<NodeLabel> = {width: 0, height: 0, rank: rank, borderType: prop};
    const prev: string | undefined = (sgNode[prop] as string[])[rank - 1];
    const curr: string = addDummyNode(graph, "border", label, prefix);
    (sgNode[prop] as string[])[rank] = curr;
    graph.setParent(curr, sg);
    if (prev) {
        graph.setEdge(prev, curr, {weight: 1});
    }
}

/**
 * Transforms a point from subgraph-local coordinates to parent context coordinates.
 * @param x X in subgraph
 * @param y Y in subgraph
 * @param clusterX X of cluster node in parent
 * @param clusterY Y of cluster node in parent
 * @param subgraphCenterX Center X of subgraph in subgraph coords
 * @param subgraphCenterY Center Y of subgraph in subgraph coords
 * @returns [x, y] in parent context
 */
export function toParentCoords(x: number, y: number, clusterX: number, clusterY: number, subgraphCenterX: number, subgraphCenterY: number): [number, number] {
    return [clusterX + (x - subgraphCenterX), clusterY + (y - subgraphCenterY)];
}

/**
 * Transforms a point from parent context coordinates to subgraph-local coordinates.
 * @param x X in parent
 * @param y Y in parent
 * @param clusterX X of cluster node in parent
 * @param clusterY Y of cluster node in parent
 * @param subgraphCenterX Center X of subgraph in subgraph coords
 * @param subgraphCenterY Center Y of subgraph in subgraph coords
 * @returns [x, y] in subgraph-local coords
 */
export function toSubgraphCoords(x: number, y: number, clusterX: number, clusterY: number, subgraphCenterX: number, subgraphCenterY: number): [number, number] {
    return [subgraphCenterX + (x - clusterX), subgraphCenterY + (y - clusterY)];
}
import type {EdgeLabel, Graph, GraphLabel, NodeLabel, Point} from './types';

export function adjust(graph: Graph): void {
    const rankDir = (graph.graph() as GraphLabel).rankdir?.toLowerCase();
    if (rankDir === 'lr' || rankDir === 'rl') {
        swapWidthHeight(graph);
    }
}

export function undo(graph: Graph): void {
    const rankDir = (graph.graph() as GraphLabel).rankdir?.toLowerCase();
    if (rankDir === 'bt' || rankDir === 'rl') {
        reverseY(graph);
    }

    if (rankDir === 'lr' || rankDir === 'rl') {
        swapXY(graph);
        swapWidthHeight(graph);
    }
}

function swapWidthHeight(graph: Graph): void {
    graph.nodes().forEach(node => swapWidthHeightOne(graph.node(node) as NodeLabel));
    graph.edges().forEach(edge => swapWidthHeightOne(graph.edge(edge) as EdgeLabel));
}

function swapWidthHeightOne(attrs: NodeLabel | EdgeLabel): void {
    const w = attrs.width;
    attrs.width = attrs.height;
    attrs.height = w;
}

function reverseY(graph: Graph): void {
    graph.nodes().forEach(node => reverseYOne(graph.node(node) as NodeLabel));

    graph.edges().forEach(edge => {
        const edgeLabel = graph.edge(edge) as EdgeLabel;
        edgeLabel.points?.forEach(reverseYOne);
        if (Object.hasOwn(edgeLabel, 'y')) {
            reverseYOne(edgeLabel);
        }
    });
}

function reverseYOne(attrs: NodeLabel | EdgeLabel | Point): void {
    attrs.y = -attrs.y!;
}

function swapXY(graph: Graph): void {
    graph.nodes().forEach(node => swapXYOne(graph.node(node) as NodeLabel));

    graph.edges().forEach(edge => {
        const edgeLabel = graph.edge(edge) as EdgeLabel;
        edgeLabel.points?.forEach(swapXYOne);
        if (Object.hasOwn(edgeLabel, 'x')) {
            swapXYOne(edgeLabel);
        }
    });
}

function swapXYOne(attrs: NodeLabel | EdgeLabel | Point): void {
    const x = attrs.x;
    attrs.x = attrs.y;
    attrs.y = x;
}

import * as util from "../util";
import type {Graph, NodeCollection} from '../types';

/*
 * Assigns an initial order value for each node by performing a DFS search
 * starting from nodes in the first rank. Nodes are assigned an order in their
 * rank as they are first visited.
 *
 * This approach comes from Gansner, et al., "A Technique for Drawing Directed
 * Graphs."
 *
 * Returns a layering matrix with an array per layer and each layer sorted by
 * the order of its nodes.
 */
export default function initOrder(graph: Graph, oldNodes: NodeCollection = null): string[][] {
    const visited: { [key: string]: boolean } = {};
    const simpleNodes = graph.nodes().filter(v => !graph.children(v).length);
    const simpleNodesRanks = simpleNodes.map(v => graph.node(v).rank);
    const maxRank = util.applyWithChunking(Math.max, simpleNodesRanks);
    const layers: string[][] = util.range(maxRank + 1).map(() => []);

    function dfs(v: string): void {
        if (visited[v]) return;
        visited[v] = true;
        const node = graph.node(v);
        layers[node.rank]!.push(v);
        const successors = graph.successors(v);
        if (successors) {
            const sortedSuccessors = [...successors].sort((a: string, b: string) => compareOldOrder(a, b));
            sortedSuccessors.forEach(dfs);
        }
    }

    const orderedVs = simpleNodes.sort((a, b) => graph.node(a).rank - graph.node(b).rank);
    orderedVs.forEach(dfs);

    function compareOldOrder(a: string, b: string) {
        const nodeA = graph.node(a);
        const nodeB = graph.node(b);

        return util.compareByOldOrder(oldNodes, nodeA, nodeB);
    }

    return layers;
}

import {zipObject} from "../util";
import type {Graph} from '../types';

/*
 * A function that takes a layering (an array of layers, each with an array of
 * ordererd nodes) and a graph and returns a weighted crossing count.
 *
 * Pre-conditions:
 *
 *    1. Input graph must be simple (not a multigraph), directed, and include
 *       only simple edges.
 *    2. Edges in the input graph must have assigned weights.
 *
 * Post-conditions:
 *
 *    1. The graph and layering matrix are left unchanged.
 *
 * This algorithm is derived from Barth, et al., "Bilayer Cross Counting."
 */
export default function crossCount(graph: Graph, layering: string[][]): number {
    let cc = 0;
    for (let i = 1; i < layering.length; ++i) {
        cc += twoLayerCrossCount(graph, layering[i - 1]!, layering[i]!);
    }
    return cc;
}

interface SouthEntry {
    pos: number;
    weight: number;
}

function twoLayerCrossCount(graph: Graph, northLayer: string[], southLayer: string[]): number {
    // Sort all of the edges between the north and south layers by their position
    // in the north layer and then the south. Map these edges to the position of
    // their head in the south layer.
    const southPos: { [key: string]: number } = zipObject(southLayer, southLayer.map((v, i) => i));
    const southEntries: SouthEntry[] = northLayer.flatMap(v => {
        const edges = graph.outEdges(v);
        if (!edges) return [];
        return edges.map(e => {
            return {pos: southPos[e.w]!, weight: graph.edge(e).weight};
        }).sort((a, b) => a.pos - b.pos);
    });

    // Build the accumulator tree
    let firstIndex = 1;
    while (firstIndex < southLayer.length) firstIndex <<= 1;
    const treeSize = 2 * firstIndex - 1;
    firstIndex -= 1;
    const tree = new Array(treeSize).fill(0);

    // Calculate the weighted crossings
    let cc = 0;
    southEntries.forEach((entry: SouthEntry) => {
        let index = entry.pos + firstIndex;
        tree[index] += entry.weight;
        let weightSum = 0;
        while (index > 0) {
            if (index % 2) {
                weightSum += tree[index + 1];
            }
            index = (index - 1) >> 1;
            tree[index] += entry.weight;
        }
        cc += entry.weight * weightSum;
    });

    return cc;
}

import type {Graph} from '../types';

interface BarycenterEntry {
    v: string;
    barycenter?: number;
    weight?: number;
}

export default function barycenter(graph: Graph, movable: string[] = []): BarycenterEntry[] {
    return movable.map(v => {
        const inV = graph.inEdges(v);
        if (!inV || !inV.length) {
            return {v: v};
        } else {
            const result = inV.reduce((acc, e) => {
                const edge = graph.edge(e);
                const nodeU = graph.node(e.v);
                return {
                    sum: acc.sum + (edge.weight * nodeU.order),
                    weight: acc.weight + edge.weight
                };
            }, {sum: 0, weight: 0});

            return {
                v: v,
                barycenter: result.sum / result.weight,
                weight: result.weight
            };
        }
    });
}

import * as util from "../util";
import type {Graph} from '../types';

interface BarycenterEntry {
    v: string;
    barycenter?: number;
    weight?: number;
}

interface MappedEntry {
    indegree: number;
    in: MappedEntry[];
    out: MappedEntry[];
    vs: string[];
    i: number;
    barycenter?: number;
    weight?: number;
    merged?: boolean;
    [key: string]: unknown;
}

export interface ResolvedEntry {
    vs: string[];
    i: number;
    barycenter?: number;
    weight?: number;
}

/*
 * Given a list of entries of the form {v, barycenter, weight} and a
 * constraint graph this function will resolve any conflicts between the
 * constraint graph and the barycenters for the entries. If the barycenters for
 * an entry would violate a constraint in the constraint graph then we coalesce
 * the nodes in the conflict into a new node that respects the contraint and
 * aggregates barycenter and weight information.
 *
 * This implementation is based on the description in Forster, "A Fast and
 * Simple Hueristic for Constrained Two-Level Crossing Reduction," thought it
 * differs in some specific details.
 *
 * Pre-conditions:
 *
 *    1. Each entry has the form {v, barycenter, weight}, or if the node has
 *       no barycenter, then {v}.
 *
 * Returns:
 *
 *    A new list of entries of the form {vs, i, barycenter, weight}. The list
 *    `vs` may either be a singleton or it may be an aggregation of nodes
 *    ordered such that they do not violate constraints from the constraint
 *    graph. The property `i` is the lowest original index of any of the
 *    elements in `vs`.
 */
export default function resolveConflicts(entries: BarycenterEntry[], constraintGraph: Graph): ResolvedEntry[] {
    const mappedEntries: { [key: string]: MappedEntry } = {};
    entries.forEach((entry, i) => {
        const tmp: MappedEntry = {
            indegree: 0,
            "in": [],
            out: [],
            vs: [entry.v],
            i: i
        };
        if (entry.barycenter !== undefined) {
            tmp.barycenter = entry.barycenter;
            tmp.weight = entry.weight;
        }
        mappedEntries[entry.v] = tmp;
    });

    constraintGraph.edges().forEach(e => {
        const entryV = mappedEntries[e.v];
        const entryW = mappedEntries[e.w];
        if (entryV !== undefined && entryW !== undefined) {
            entryW.indegree++;
            entryV.out.push(entryW);
        }
    });

    const sourceSet = Object.values(mappedEntries).filter(entry => !entry.indegree);

    return doResolveConflicts(sourceSet);
}

function doResolveConflicts(sourceSet: MappedEntry[]): ResolvedEntry[] {
    const entries: MappedEntry[] = [];

    function handleIn(vEntry: MappedEntry): (uEntry: MappedEntry) => void {
        return (uEntry: MappedEntry) => {
            if (uEntry.merged) {
                return;
            }
            if (uEntry.barycenter === undefined ||
                vEntry.barycenter === undefined ||
                uEntry.barycenter >= vEntry.barycenter) {
                mergeEntries(vEntry, uEntry);
            }
        };
    }

    function handleOut(vEntry: MappedEntry): (wEntry: MappedEntry) => void {
        return (wEntry: MappedEntry) => {
            wEntry["in"].push(vEntry);
            if (--wEntry.indegree === 0) {
                sourceSet.push(wEntry);
            }
        };
    }

    while (sourceSet.length) {
        const entry = sourceSet.pop()!;
        entries.push(entry);
        entry["in"].reverse().forEach(handleIn(entry));
        entry.out.forEach(handleOut(entry));
    }

    return entries.filter(entry => !entry.merged).map(entry => {
        return util.pick(entry, ["vs", "i", "barycenter", "weight"]) as ResolvedEntry;
    }) as ResolvedEntry[];
}

function mergeEntries(target: MappedEntry, source: MappedEntry): void {
    let sum = 0;
    let weight = 0;

    if (target.weight) {
        sum += target.barycenter! * target.weight;
        weight += target.weight;
    }

    if (source.weight) {
        sum += source.barycenter! * source.weight;
        weight += source.weight;
    }

    target.vs = source.vs.concat(target.vs);
    target.barycenter = sum / weight;
    target.weight = weight;
    target.i = Math.min(source.i, target.i);
    source.merged = true;
}

import * as util from "../util";
import type {Graph, NodeCollection} from '../types';
import {ResolvedEntry} from "./resolve-conflicts";

interface SortEntry {
    vs: string[];
    i: number;
    barycenter?: number;
    weight?: number;
}

interface SortResult {
    vs: string[];
    barycenter?: number;
    weight?: number;
}

export default function sort(
    entries: SortEntry[],
    reversedPairs?: Record<string, ResolvedEntry> | boolean,
    oldNodes?: NodeCollection,
    graph?: Graph | null,
    biasRight?: boolean
): SortResult {
    let resolvedReversedPairs: Record<string, ResolvedEntry> = {};
    let resolvedOldNodes: NodeCollection = null;
    let resolvedGraph: Graph | null = null;
    let resolvedBiasRight: boolean | undefined = biasRight;

    if (typeof reversedPairs === "boolean") {
        resolvedBiasRight = reversedPairs;
        resolvedReversedPairs = {};
    } else if (reversedPairs) {
        resolvedReversedPairs = reversedPairs;
        resolvedOldNodes = oldNodes ?? null;
        resolvedGraph = graph ?? null;
    }

    const parts = util.partition(entries, entry => {
        return Object.hasOwn(entry, "barycenter");
    });
    const sortable = parts.lhs;
    const unsortable = parts.rhs.sort((a, b) => b.i - a.i);
    const vs: string[][] = [];
    let sum = 0;
    let weight = 0;
    let vsIndex = 0;

    sortable.sort(compareWithOldOrder(resolvedGraph, resolvedOldNodes, !!resolvedBiasRight));

    // re-inserts the links, that are already in sortable but reversed, next to its reverse counterpart
    for (const [key, value] of Object.entries(resolvedReversedPairs)) {
        const keyIndex = sortable.findIndex(entry => entry.vs[0] === key);
        sortable.splice(keyIndex + 1, 0, value);
    }

    vsIndex = consumeUnsortable(vs, unsortable, vsIndex);

    sortable.forEach(entry => {
        vsIndex += entry.vs.length;
        vs.push(entry.vs);
        sum += entry.barycenter! * entry.weight!;
        weight += entry.weight!;
        vsIndex = consumeUnsortable(vs, unsortable, vsIndex);
    });

    const result: SortResult = {vs: vs.flat(1) as string[]};
    if (weight) {
        result.barycenter = sum / weight;
        result.weight = weight;
    }
    return result;
}

function consumeUnsortable(vs: string[][], unsortable: SortEntry[], index: number): number {
    let last: SortEntry | undefined;
    while (unsortable.length && (last = unsortable[unsortable.length - 1])!.i <= index) {
        unsortable.pop();
        vs.push(last!.vs);
        index++;
    }
    return index;
}

function compareWithOldOrder(graph: Graph | null, oldNodes: NodeCollection, bias: boolean): (entryV: SortEntry, entryW: SortEntry) => number {
    return (entryV: SortEntry, entryW: SortEntry) => {
        if (entryV.barycenter! < entryW.barycenter!) {
            return -1;
        } else if (entryV.barycenter! > entryW.barycenter!) {
            return 1;
        }

        if (graph && (typeof entryV.vs[0] === "string" || typeof entryW.vs[0] === "string")) {
            const nodeV = graph.node(entryV.vs[0]!);
            const nodeW = graph.node(entryW.vs[0]!);
            const byOldOrder = util.compareByOldOrder(oldNodes, nodeV, nodeW);
            if (byOldOrder !== 0) {
                return byOldOrder;
            }
        }

        return !bias ? entryV.i - entryW.i : entryW.i - entryV.i;
    };
}

