import barycenter from "./barycenter";
import resolveConflicts, {ResolvedEntry} from "./resolve-conflicts";
import sort from "./sort";
import type {Graph, NodeCollection} from '../types';

interface SubgraphResult {
    vs: string[];
    barycenter?: number;
    weight?: number;
}

interface BarycenterEntry {
    v: string;
    barycenter?: number;
    weight?: number;
}

export default function sortSubgraph(
    graph: Graph,
    v: string,
    constraintGraph: Graph,
    oldNodes?: NodeCollection | boolean,
    biasRight?: boolean
): SubgraphResult & { result: SubgraphResult, usedBias: boolean } {
    let resolvedOldNodes: NodeCollection = null;
    let resolvedBiasRight: boolean | undefined = biasRight;

    if (typeof oldNodes === "boolean") {
        resolvedBiasRight = oldNodes;
        resolvedOldNodes = null;
    } else if (oldNodes !== undefined) {
        resolvedOldNodes = oldNodes;
    }

    let movable = graph.children(v);
    const node = graph.node(v);
    const bl: string | undefined = node ? (node.borderLeft) : undefined;
    const br: string | undefined = node ? (node.borderRight) : undefined;
    const subgraphs: { [key: string]: SubgraphResult } = {};

    if (bl) {
        movable = movable.filter(w => w !== bl && w !== br);
    }

    const barycenters = barycenter(graph, movable);
    barycenters.forEach(entry => {
        if (graph.children(entry.v).length) {
            const {result: subgraphResult} = sortSubgraph(graph, entry.v, constraintGraph, resolvedOldNodes, resolvedBiasRight);
            subgraphs[entry.v] = subgraphResult;
            if (Object.hasOwn(subgraphResult, "barycenter")) {
                mergeBarycenters(entry, subgraphResult);
            }
        }
    });

    const entries = resolveConflicts(barycenters, constraintGraph);
    expandSubgraphs(entries, subgraphs);

    const reversedPairs: Record<string, ResolvedEntry> = {};
    let usedBias = false;
    for (let i = 0; i < entries.length; i++) {
        for (let j = i + 1; j < entries.length; j++) {
            if (!entries[i] || !entries[j] || !entries[i]?.barycenter || !entries[j]?.barycenter) {
                continue;
            }
            if (entries[i]?.barycenter === entries[j]!.barycenter) {
                const nameI = entries[i]?.vs[0] ?? "";
                const nameJ = entries[j]?.vs[0] ?? "";
                const nodeI = graph.node(nameI);
                const nodeJ = graph.node(nameJ);

                if (nodeI.dummy === "edge" && nodeJ.dummy === "edge" &&
                    nodeI.edgeObj?.v === nodeJ.edgeObj?.v &&
                    nodeI.edgeObj?.w === nodeJ.edgeObj?.w) {
                    if (nodeI.edgeLabel.reversed) {
                        reversedPairs[nameJ] = entries[i]!;
                        entries.splice(i, 1);
                        i--;
                        break;
                    } else {
                        reversedPairs[nameI] = entries[j]!;
                        entries.splice(j, 1);
                        j--;
                    }

                } else {
                    usedBias = true;
                }
            }
        }
    }

    const result = sort(entries, reversedPairs, resolvedOldNodes, graph, resolvedBiasRight);

    if (bl && br) {
        result.vs = [bl, result.vs, br].flat(1) as string[];
        const blPredecessors = graph.predecessors(bl);
        if (blPredecessors && blPredecessors.length) {
            const blPred = graph.node(blPredecessors[0]!);
            const brPredecessors = graph.predecessors(br);
            const brPred = graph.node(brPredecessors![0]!);
            if (!Object.hasOwn(result, "barycenter")) {
                result.barycenter = 0;
                result.weight = 0;
            }
            result.barycenter = (result.barycenter! * result.weight! +
                blPred.order! + brPred.order!) / (result.weight! + 2);
            result.weight! += 2;
        }
    }

    Object.defineProperty(result, "result", { value: result, enumerable: false, configurable: true, writable: true });
    Object.defineProperty(result, "usedBias", { value: usedBias, enumerable: false, configurable: true, writable: true });
    return result as SubgraphResult & { result: SubgraphResult, usedBias: boolean };
}

function expandSubgraphs(entries: { vs: string[] }[], subgraphs: { [key: string]: SubgraphResult }): void {
    entries.forEach(entry => {
        entry.vs = entry.vs.flatMap(v => {
            if (subgraphs[v]) {
                return subgraphs[v].vs;
            }
            return v;
        });
    });
}

function mergeBarycenters(target: BarycenterEntry, other: SubgraphResult): void {
    if (target.barycenter !== undefined) {
        target.barycenter = (target.barycenter * target.weight! +
                other.barycenter! * other.weight!) /
            (target.weight! + other.weight!);
        target.weight! += other.weight!;
    } else {
        target.barycenter = other.barycenter;
        target.weight = other.weight;
    }
}

import {Graph} from "../graph-lib";
import * as util from "../util";
import type {Graph as GraphType} from '../types';

interface LayerGraphLabel {
    root: string;
}

/*
 * Constructs a graph that can be used to sort a layer of nodes. The graph will
 * contain all base and subgraph nodes from the request layer in their original
 * hierarchy and any edges that are incident on these nodes and are of the type
 * requested by the "relationship" parameter.
 *
 * Nodes from the requested rank that do not have parents are assigned a root
 * node in the output graph, which is set in the root graph attribute. This
 * makes it easy to walk the hierarchy of movable nodes during ordering.
 *
 * Pre-conditions:
 *
 *    1. Input graph is a DAG
 *    2. Base nodes in the input graph have a rank attribute
 *    3. Subgraph nodes in the input graph has minRank and maxRank attributes
 *    4. Edges have an assigned weight
 *    5. If `nodesWithRank` is not undefined, it must contains only the nodes
 *       which belong to `g` and belong to `rank`.
 *
 * Post-conditions:
 *
 *    1. Output graph has all nodes in the movable rank with preserved
 *       hierarchy.
 *    2. Root nodes in the movable layer are made children of the node
 *       indicated by the root attribute of the graph.
 *    3. Non-movable nodes incident on movable nodes, selected by the
 *       relationship parameter, are included in the graph (without hierarchy).
 *    4. Edges incident on movable nodes, selected by the relationship
 *       parameter, are added to the output graph.
 *    5. The weights for copied edges are aggregated as need, since the output
 *       graph is not a multi-graph.
 */
export default function buildLayerGraph(
    graph: GraphType,
    rank: number,
    relationship: "inEdges" | "outEdges",
    nodesWithRank?: string[]
): GraphType {
    if (!nodesWithRank) {
        nodesWithRank = graph.nodes();
    }
    const root = createRootNode(graph);
    const result = new Graph({compound: true})
        .setGraph({root: root} as LayerGraphLabel)
        .setDefaultNodeLabel((v: string) => graph.node(v)) as GraphType;

    nodesWithRank.forEach((v: string) => {
        const node = graph.node(v);
        const parent = graph.parent(v);

        if (node.rank === rank || node.minRank! <= rank && rank <= node.maxRank!) {
            result.setNode(v);
            result.setParent(v, parent || root);

            // This assumes we have only short edges!
            const edges = graph[relationship](v);
            if (edges) {
                edges.forEach(e => {
                    const u = e.v === v ? e.w : e.v;
                    const edge = result.edge(u, v);
                    const weight = edge !== undefined ? edge.weight : 0;
                    result.setEdge(u, v, {weight: graph.edge(e).weight + weight});
                });
            }

            if (Object.hasOwn(node, "minRank")) {
                result.setNode(v, {
                    borderLeft: node.borderLeft![rank],
                    borderRight: node.borderRight![rank]
                });
            }
        }
    });

    return result;
}

function createRootNode(graph: GraphType): string {
    let v: string;
    while (graph.hasNode((v = util.uniqueId("_root")))) ;
    return v;
}

import type {Graph} from '../types';

export default function addSubgraphConstraints(graph: Graph, constraintGraph: Graph, vs: string[]): void {
    const prev: { [key: string]: string } = {};
    let rootPrev: string | undefined;

    vs.forEach(v => {
        let child: string | undefined | void = graph.parent(v);
        let parent: string | undefined | void;
        let prevChild: string | undefined;
        while (child) {
            parent = graph.parent(child);
            if (parent) {
                prevChild = prev[parent];
                prev[parent] = child;
            } else {
                prevChild = rootPrev;
                rootPrev = child;
            }
            if (prevChild && prevChild !== child) {
                constraintGraph.setEdge(prevChild, child);
                return;
            }
            child = parent;
        }
    });

    /*
    function dfs(v) {
      var children = v ? g.children(v) : g.children();
      if (children.length) {
        var min = Number.POSITIVE_INFINITY,
            subgraphs = [];
        children.forEach(function(child) {
          var childMin = dfs(child);
          if (g.children(child).length) {
            subgraphs.push({ v: child, order: childMin });
          }
          min = Math.min(min, childMin);
        });
        _.sortBy(subgraphs, "order").reduce(function(prev, curr) {
          cg.setEdge(prev.v, curr.v);
          return curr;
        });
        return min;
      }
      return g.node(v).order;
    }
    dfs(undefined);
    */
}

// Use LayoutContext and coordinate-system transforms for all node ordering
// This will ensure correct ordering for per-cluster direction
import initOrder from "./init-order";
import crossCount from "./cross-count";
import sortSubgraph from "./sort-subgraph";
import buildLayerGraph from "./build-layer-graph";
import addSubgraphConstraints from "./add-subgraph-constraints";
import {Graph} from "../graph-lib";
import * as util from "../util";
import type {Graph as GraphType, NodeCollection, OrderConstraint, OrderOptions} from '../types';

/*
 * Applies heuristics to minimize edge crossings in the graph and sets the best
 * order solution as an order attribute on each node.
 *
 * Pre-conditions:
 *
 *    1. Graph must be DAG
 *    2. Graph nodes must be objects with a "rank" attribute
 *    3. Graph edges must have the "weight" attribute
 *
 * Post-conditions:
 *
 *    1. Graph nodes will have an "order" attribute based on the results of the
 *       algorithm.
 */
export default function order(graph: GraphType, opts: OrderOptions = {}, oldNodes: NodeCollection = null): void {
    if (typeof opts.customOrder === 'function') {
        opts.customOrder(graph, order);
        return;
    }

    const maxRank = util.maxRank(graph);
    const downLayerGraphs = buildLayerGraphs(graph, util.range(1, maxRank + 1), "inEdges");
    const upLayerGraphs = buildLayerGraphs(graph, util.range(maxRank - 1, -1, -1), "outEdges");

    let layering = initOrder(graph, oldNodes);
    assignOrder(graph, layering);

    if (opts.disableOptimalOrderHeuristic) {
        return;
    }

    let bestCC = Number.POSITIVE_INFINITY;
    let best: string[][];

    const constraints = opts.constraints || [];
    for (let i = 0, lastBest = 0; lastBest < 4; ++i, ++lastBest) {
        sweepLayerGraphs(i % 2 ? downLayerGraphs : upLayerGraphs, i % 4 >= 2, constraints, oldNodes);

        layering = util.buildLayerMatrix(graph);
        const cc = crossCount(graph, layering);
        if (cc < bestCC) {
            lastBest = 0;
            best = Object.assign({}, layering);
            bestCC = cc;
        } else if (cc === bestCC) {
            best = structuredClone(layering);
        }
    }

    assignOrder(graph, best!);
}

function buildLayerGraphs(graph: GraphType, ranks: number[], relationship: "inEdges" | "outEdges"): GraphType[] {
    // Build an index mapping from rank to the nodes with that rank.
    // This helps to avoid a quadratic search for all nodes with the same rank as
    // the current node.
    const nodesByRank = new Map<number, string[]>();
    const addNodeToRank = (rank: number, node: string): void => {
        if (!nodesByRank.has(rank)) {
            nodesByRank.set(rank, []);
        }
        nodesByRank.get(rank)!.push(node);
    };

    // Visit the nodes in their original order in the graph, and add each
    // node to the ranks(s) that it belongs to.
    for (const v of graph.nodes()) {
        const node = graph.node(v);
        if (typeof node.rank === "number") {
            addNodeToRank(node.rank, v);
        }
        // If there is a range of ranks, add it to each, but skip the `node.rank` which
        // has already had the node added.
        if (typeof node.minRank === "number" && typeof node.maxRank === "number") {
            for (let r = node.minRank; r <= node.maxRank; r++) {
                if (r !== node.rank) {
                    // Don't add this node to its `node.rank` twice.
                    addNodeToRank(r, v);
                }
            }
        }
    }

    return ranks.map(function (rank) {
        return buildLayerGraph(graph, rank, relationship, nodesByRank.get(rank) || []);
    });
}

function sweepLayerGraphs(layerGraphs: GraphType[], switchBias: boolean, constraints: OrderConstraint[], oldNodes: NodeCollection): void {
    let biasRight: boolean = true;
    const cg = new Graph() as GraphType;
    layerGraphs.forEach(function (lg) {
        constraints.forEach(con => cg.setEdge(con.left, con.right));

        const root = (lg.graph() as { root: string }).root;
        const {result: sorted, usedBias} = sortSubgraph(lg, root, cg, oldNodes, biasRight);
        if (switchBias && usedBias) {
            biasRight = !biasRight;
        }
        sorted.vs.forEach((v, i) => lg.node(v).order = i);
        addSubgraphConstraints(lg, cg, sorted.vs);
    });
}

function assignOrder(graph: GraphType, layering: string[][]): void {
    Object.values(layering).forEach(layer => layer.forEach((v, i) => graph.node(v).order = i));
}

import {Graph} from "../graph-lib";
import * as util from "../util";
import type {EdgeLabel, GraphLabel, NodeLabel} from "../types";

/*
 * This module provides coordinate assignment based on Brandes and Köpf, "Fast
 * and Simple Horizontal Coordinate Assignment."
 */

export {
    positionX,
    findType1Conflicts,
    findType2Conflicts,
    addConflict,
    hasConflict,
    verticalAlignment,
    horizontalCompaction,
    alignCoordinates,
    findSmallestWidthAlignment,
    balance
};

type Conflicts = { [key: string]: { [key: string]: boolean } };
type PositionMap = { [key: string]: number };
type AlignmentResult = { root: { [key: string]: string }, align: { [key: string]: string } };
type XssMap = { [key: string]: PositionMap };

/*
 * Marks all edges in the graph with a type-1 conflict with the "type1Conflict"
 * property. A type-1 conflict is one where a non-inner segment crosses an
 * inner segment. An inner segment is an edge with both incident nodes marked
 * with the "dummy" property.
 *
 * This algorithm scans layer by layer, starting with the second, for type-1
 * conflicts between the current layer and the previous layer. For each layer
 * it scans the nodes from left to right until it reaches one that is incident
 * on an inner segment. It then scans predecessors to determine if they have
 * edges that cross that inner segment. At the end a final scan is done for all
 * nodes on the current rank to see if they cross the last visited inner
 * segment.
 *
 * This algorithm (safely) assumes that a dummy node will only be incident on a
 * single node in the layers being scanned.
 */
function findType1Conflicts(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, layering: string[][]): Conflicts {
    const conflicts: Conflicts = {};

    function visitLayer(prevLayer: string[], layer: string[]): string[] {
        let
            // last visited node in the previous layer that is incident on an inner
            // segment.
            k0 = 0,
            // Tracks the last node in this layer scanned for crossings with a type-1
            // segment.
            scanPos = 0;
        const prevLayerLength = prevLayer.length,
            lastNode = layer[layer.length - 1];

        layer.forEach((v, i) => {
            const w: string | undefined = findOtherInnerSegmentNode(graph, v);
            const k1: number = w ? graph.node(w).order! : prevLayerLength;

            if (w || v === lastNode) {
                layer.slice(scanPos, i + 1).forEach(scanNode => {
                    const preds = graph.predecessors(scanNode);
                    if (preds) {
                        preds.forEach(u => {
                            const uLabel = graph.node(u) as NodeLabel;
                            const uPos: number = uLabel.order!;
                            if ((uPos < k0 || k1 < uPos) &&
                                !(uLabel.dummy && (graph.node(scanNode) as NodeLabel).dummy)) {
                                addConflict(conflicts, u, scanNode);
                            }
                        });
                    }
                });
                scanPos = i + 1;
                k0 = k1;
            }
        });

        return layer;
    }

    if (layering.length) {
        layering.reduce(visitLayer);
    }

    return conflicts;
}

function findType2Conflicts(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, layering: string[][]): Conflicts {
    const conflicts: Conflicts = {};

    function scan(south: string[], southPos: number, southEnd: number, prevNorthBorder: number, nextNorthBorder: number): void {
        util.range(southPos, southEnd).forEach(i => {
            const v = south[i];
            if (v === undefined) return;
            if ((graph.node(v) as NodeLabel).dummy) {
                const preds = graph.predecessors(v);
                if (preds) {
                    preds.forEach(u => {
                        if (u === undefined) return;
                        const uNode = graph.node(u) as NodeLabel;
                        if (uNode.dummy &&
                            (uNode.order! < prevNorthBorder || uNode.order! > nextNorthBorder)) {
                            addConflict(conflicts, u, v);
                        }
                    });
                }
            }
        });
    }


    function visitLayer(north: string[], south: string[]): string[] {
        let prevNorthPos = -1;
        let nextNorthPos = -1;
        let southPos = 0;

        south.forEach((v, southLookahead) => {
            if ((graph.node(v) as NodeLabel).dummy === "border") {
                const predecessors = graph.predecessors(v);
                if (predecessors && predecessors.length) {
                    const firstPred = predecessors[0];
                    if (firstPred === undefined) return;
                    nextNorthPos = (graph.node(firstPred) as NodeLabel).order!;
                    scan(south, southPos, southLookahead, prevNorthPos, nextNorthPos);
                    southPos = southLookahead;
                    prevNorthPos = nextNorthPos;
                }
            }
            scan(south, southPos, south.length, nextNorthPos, north.length);
        });

        return south;
    }

    if (layering.length) {
        layering.reduce(visitLayer);
    }

    return conflicts;
}

function findOtherInnerSegmentNode(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, v: string): string | undefined {
    if ((graph.node(v) as NodeLabel).dummy) {
        const preds = graph.predecessors(v);
        if (preds) {
            return preds.find(u => (graph.node(u) as NodeLabel).dummy);
        }
    }
    return undefined;
}

function addConflict(conflicts: Conflicts, v: string, w: string): void {
    if (v > w) {
        const tmp = v;
        v = w;
        w = tmp;
    }

    let conflictsV = conflicts[v];
    if (!conflictsV) {
        conflicts[v] = conflictsV = {};
    }
    conflictsV[w] = true;
}

function hasConflict(conflicts: Conflicts, v: string, w: string): boolean {
    if (v > w) {
        const tmp = v;
        v = w;
        w = tmp;
    }
    const conflictsV = conflicts[v];
    return conflictsV !== undefined && Object.hasOwn(conflictsV, w);
}

/*
 * Try to align nodes into vertical "blocks" where possible. This algorithm
 * attempts to align a node with one of its median neighbors. If the edge
 * connecting a neighbor is a type-1 conflict then we ignore that possibility.
 * If a previous node has already formed a block with a node after the node
 * we're trying to form a block with, we also ignore that possibility - our
 * blocks would be split in that scenario.
 */
function verticalAlignment(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    layering: string[][],
    conflicts: Conflicts,
    neighborFn: (v: string) => string[],
    corePath?: string[],
): AlignmentResult {
    const root: { [key: string]: string } = {};
    const align: { [key: string]: string } = {};
    const pos: PositionMap = {};

    // We cache the position here based on the layering because the graph and
    // layering may be out of sync. The layering matrix is manipulated to
    // generate different extreme alignments.
    layering.forEach(layer => {
        layer.forEach((v, order) => {
            root[v] = v;
            align[v] = v;
            pos[v] = order;
        });
    });

    layering.forEach(layer => {
        let prevIdx: number = -1;
        let alreadyAlignedIndex: number = -1;
        let hasShifted:boolean = false;
        let modifiedLayer = layer;
        const coreNodeIndex: number = layer.findIndex(v => {
            return corePath?.includes(v) ||
                (isInCorePath(v, graph, corePath));
        });
        if (coreNodeIndex > 0) { // -1 = not found; 0 changes nothing
            // shallow copy because the original layering is used afterward
            modifiedLayer = [layer[coreNodeIndex]!, ...layer.slice(0, coreNodeIndex), ...layer.slice(coreNodeIndex + 1)];
            hasShifted = true;
        }
        modifiedLayer.forEach(v => {
            let wsRaw = neighborFn(v);
            if (wsRaw && wsRaw.length) {
                if (corePath?.includes(v)) {
                    wsRaw = wsRaw.filter((w) =>{
                        return isInCorePath(w, graph, corePath);
                    });
                }
                const ws: string[] = wsRaw.sort((a, b) => {
                    const posA = pos[a];
                    const posB = pos[b];
                    return (posA !== undefined ? posA : 0) - (posB !== undefined ? posB : 0);
                });
                const mp: number = (ws.length - 1) / 2;
                for (let i = Math.floor(mp), il = Math.ceil(mp); i <= il; ++i) {
                    const w: string | undefined = ws[i];
                    if (w === undefined) continue;
                    const posW = pos[w];
                    if (posW !== undefined && align[v] === v &&
                        prevIdx < posW &&
                        pos[w] !== alreadyAlignedIndex &&
                        !hasConflict(conflicts, v, w)) {
                        const rootW = root[w];
                        if (rootW !== undefined) {
                            align[w] = v;
                            align[v] = root[v] = rootW;
                            prevIdx = posW;
                            if (hasShifted) {
                                // if a core process node was shifted to the front of the layer
                                prevIdx = -1; // make sure the alignment can continue as usual after
                                alreadyAlignedIndex = pos[w] ?? -1; // but do not align another node to the same one
                                hasShifted = false; // only do this once
                            }
                        }
                    }
                }
            }
        });
    });

    return {root: root, align: align};
}

function horizontalCompaction(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    layering: string[][],
    root: { [key: string]: string },
    align: { [key: string]: string },
    reverseSep: boolean = false
): PositionMap {
    // This portion of the algorithm differs from BK due to a number of problems.
    // Instead of their algorithm we construct a new block graph and do two
    // sweeps. The first sweep places blocks with the smallest possible
    // coordinates. The second sweep removes unused space by moving blocks to the
    // greatest coordinates without violating separation.
    const xs: PositionMap = {};
    const blockG: Graph<NodeLabel, EdgeLabel, number> = buildBlockGraph(graph, layering, root, reverseSep);
    const borderType: string = reverseSep ? "borderLeft" : "borderRight";

    function iterate(setXsFunc: (elem: string) => void, nextNodesFunc: (elem: string) => string[]): void {
        const stack: string[] = blockG.nodes().slice(); // Create a copy of the node list.
        const visited: { [key: string]: boolean } = {};
        let elem: string | undefined = stack.pop();

        while (elem) {
            if (visited[elem]) {
                setXsFunc(elem);
            } else {
                visited[elem] = true;
                // Put the element back into the stack, so that we can process it
                // again after all of the `nextNodesFunc` items are processed.
                stack.push(elem);
                for (const nextElem of nextNodesFunc(elem)) {
                    stack.push(nextElem);
                }
            }

            elem = stack.pop();
        }
    }

    // First pass, assign smallest coordinates
    function pass1(elem: string): void {
        const inEdges = blockG.inEdges(elem);
        if (inEdges) {
            xs[elem] = inEdges.reduce((acc, e) => {
                const xsV = xs[e.v] ?? 0;
                const edgeWeight = blockG.edge(e);
                return Math.max(acc, xsV + (edgeWeight !== undefined ? edgeWeight : 0));
            }, 0);
        } else {
            xs[elem] = 0;
        }
    }

    // Second pass, assign greatest coordinates
    function pass2(elem: string): void {
        const outEdges = blockG.outEdges(elem);
        let min = Number.POSITIVE_INFINITY;
        if (outEdges) {
            min = outEdges.reduce((acc, e) => {
                const xsW = xs[e.w];
                const edgeWeight = blockG.edge(e);
                return Math.min(acc, (xsW !== undefined ? xsW : 0) - (edgeWeight !== undefined ? edgeWeight : 0));
            }, Number.POSITIVE_INFINITY);
        }

        const node = graph.node(elem) as NodeLabel;
        if (min !== Number.POSITIVE_INFINITY && node.borderType !== borderType) {
            xs[elem] = Math.max(xs[elem] !== undefined ? xs[elem] : 0, min);
        }
    }

    function predecessorsWrapper(elem: string): string[] {
        return blockG.predecessors(elem) || [];
    }

    function successorsWrapper(elem: string): string[] {
        return blockG.successors(elem) || [];
    }

    iterate(pass1, predecessorsWrapper);
    iterate(pass2, successorsWrapper);

    // Assign x coordinates to all nodes
    Object.keys(align).forEach(v => {
        const rootV = root[v];
        if (rootV !== undefined) {
            xs[v] = xs[rootV] ?? 0;
        }
    });

    return xs;
}


function buildBlockGraph(
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    layering: string[][],
    root: { [key: string]: string },
    reverseSep: boolean
): Graph<NodeLabel, EdgeLabel, number> {
    const blockGraph = new Graph<NodeLabel, EdgeLabel, number>();
    const graphLabel: GraphLabel = graph.graph();
    const sepFn: (g: Graph<GraphLabel, NodeLabel, EdgeLabel>, v: string, u: string) => number = sep(graphLabel.nodesep!, graphLabel.edgesep!, reverseSep);

    layering.forEach(layer => {
        let u: string | undefined;
        layer.forEach(v => {
            const vRoot = root[v];
            if (vRoot !== undefined) {
                blockGraph.setNode(vRoot);
                if (u !== undefined) {
                    const uRoot = root[u];
                    if (uRoot !== undefined) {
                        const prevMax: number | undefined = blockGraph.edge(uRoot, vRoot);
                        blockGraph.setEdge(uRoot, vRoot, Math.max(sepFn(graph, v, u), prevMax || 0));
                    }
                }
                u = v;
            }
        });
    });

    return blockGraph;
}

/*
 * Returns the alignment that has the smallest width of the given alignments.
 */
function findSmallestWidthAlignment(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, xss: XssMap): PositionMap {
    return Object.values(xss).reduce((currentMinAndXs: [number, PositionMap | null], xs: PositionMap) => {
        let max = Number.NEGATIVE_INFINITY;
        let min = Number.POSITIVE_INFINITY;

        Object.entries(xs).forEach(([v, x]) => {
            const halfWidth: number = width(graph, v) / 2;

            max = Math.max(x + halfWidth, max);
            min = Math.min(x - halfWidth, min);
        });

        const newMin: number = max - min;
        if (newMin < currentMinAndXs[0]) {
            currentMinAndXs = [newMin, xs];
        }
        return currentMinAndXs;
    }, [Number.POSITIVE_INFINITY, null])[1]!;
}

/*
 * Align the coordinates of each of the layout alignments such that
 * left-biased alignments have their minimum coordinate at the same point as
 * the minimum coordinate of the smallest width alignment and right-biased
 * alignments have their maximum coordinate at the same point as the maximum
 * coordinate of the smallest width alignment.
 */
function alignCoordinates(xss: XssMap, alignTo: PositionMap): void {
    const alignToVals: number[] = Object.values(alignTo);
    const alignToMin: number = util.applyWithChunking(Math.min, alignToVals);
    const alignToMax: number = util.applyWithChunking(Math.max, alignToVals);

    ["u", "d"].forEach(vert => {
        ["l", "r"].forEach(horiz => {
            const alignment: string = vert + horiz;
            const xs: PositionMap | undefined = xss[alignment];

            if (!xs || xs === alignTo) return;

            const xsVals: number[] = Object.values(xs);
            let delta: number = alignToMin - util.applyWithChunking(Math.min, xsVals);
            if (horiz !== "l") {
                delta = alignToMax - util.applyWithChunking(Math.max, xsVals);
            }

            if (delta) {
                xss[alignment] = util.mapValues(xs, x => x + delta);
            }
        });
    });
}

function balance(xss: XssMap, align: string | undefined = undefined): PositionMap {
    const ulMap = xss.ul;
    if (!ulMap) {
        return {};
    }
    return util.mapValues(ulMap, (num: number, v: string) => {
        if (align) {
            const alignmentKey = align.toLowerCase();
            const alignment = xss[alignmentKey];
            if (alignment && alignment[v] !== undefined) {
                return alignment[v];
            }
        }
        const xs: number[] = Object.values(xss).map(xs => {
            const val = xs[v];
            return val !== undefined ? val : 0;
        }).sort((a, b) => a - b);
        return ((xs[1] ?? 0) + (xs[2] ?? 0)) / 2;
    });
}

function positionX(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, corePath?: string[]): PositionMap {
    const layering: string[][] = util.buildLayerMatrix(graph);
    const conflicts: Conflicts = Object.assign(
        findType1Conflicts(graph, layering),
        findType2Conflicts(graph, layering));

    const xss: XssMap = {};
    let adjustedLayering: string[][];
    ["u", "d"].forEach(vert => {
        adjustedLayering = vert === "u" ? layering : Object.values(layering).reverse();
        ["l", "r"].forEach(horiz => {
            if (horiz === "r") {
                adjustedLayering = adjustedLayering.map(inner => {
                    return Object.values(inner).reverse();
                });
            }

            const neighborFn = (v: string): string[] => {
                const result = vert === "u" ? graph.predecessors(v) : graph.successors(v);
                return result || [];
            };
            const align: AlignmentResult = verticalAlignment(graph, adjustedLayering, conflicts, neighborFn, corePath);
            let xs: PositionMap = horizontalCompaction(graph, adjustedLayering,
                align.root, align.align, horiz === "r");
            if (horiz === "r") {
                xs = util.mapValues(xs, x => -x);
            }
            xss[vert + horiz] = xs;
        });
    });


    const smallestWidth: PositionMap = findSmallestWidthAlignment(graph, xss);
    alignCoordinates(xss, smallestWidth);
    return balance(xss, graph.graph().align);
}

function sep(nodeSep: number, edgeSep: number, reverseSep: boolean): (g: Graph<GraphLabel, NodeLabel, EdgeLabel>, v: string, w: string) => number {
    return (g: Graph<GraphLabel, NodeLabel, EdgeLabel>, v: string, w: string): number => {
        const vLabel = g.node(v) as NodeLabel;
        const wLabel = g.node(w) as NodeLabel;
        let sum = 0;
        let delta: number | undefined;

        sum += vLabel.width / 2;
        if (Object.hasOwn(vLabel, "labelpos")) {
            switch ((vLabel.labelpos as string).toLowerCase()) {
            case "l":
                delta = -vLabel.width / 2;
                break;
            case "r":
                delta = vLabel.width / 2;
                break;
            }
        }
        if (delta) {
            sum += reverseSep ? delta : -delta;
        }
        delta = undefined;

        sum += (vLabel.dummy ? edgeSep : nodeSep) / 2;
        sum += (wLabel.dummy ? edgeSep : nodeSep) / 2;

        sum += wLabel.width / 2;
        if (Object.hasOwn(wLabel, "labelpos")) {
            switch ((wLabel.labelpos as string).toLowerCase()) {
            case "l":
                delta = wLabel.width / 2;
                break;
            case "r":
                delta = -wLabel.width / 2;
                break;
            }
        }
        if (delta) {
            sum += reverseSep ? delta : -delta;
        }

        return sum;
    };
}

function width(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, v: string): number {
    return (graph.node(v) as NodeLabel).width;
}

function isInCorePath(v: string, graph: Graph, corePath: string[] | undefined) {
    if (!corePath) return false;
    const edge = graph.node(v)?.edgeObj;
    if (!edge || graph.node(v).edgeLabel.reversed) return false;

    const sourceIndex = corePath.indexOf(edge?.v);
    const targetIndex = corePath.indexOf(edge?.w);

    return sourceIndex !== -1 && targetIndex !== -1 &&
        sourceIndex === (targetIndex + 1) % corePath.length ||
        sourceIndex === (targetIndex - 1) % corePath.length;
}

import * as util from "../util";
import {positionX} from "./bk";
import type {Graph} from '@dagrejs/graphlib';
import type {EdgeLabel, GraphLabel, NodeLabel} from "../types";

export {position};

function position(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>, corePath?: string[]): void {
    graph = util.asNonCompoundGraph(graph);

    positionY(graph);
    Object.entries(positionX(graph, corePath)).forEach(([v, x]) => graph.node(v).x = x);
}

function positionY(graph: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const layering: string[][] = util.buildLayerMatrix(graph);
    const graphLabel = graph.graph();
    const rankSep: number = graphLabel.ranksep!;
    const rankAlign: string | undefined = graphLabel.rankalign;
    let prevY = 0;
    layering.forEach(layer => {
        const maxHeight: number = layer.reduce((acc: number, v: string) => {
            const height: number = graph.node(v).height ?? 0;
            if (acc > height) {
                return acc;
            } else {
                return height;
            }
        }, 0);
        layer.forEach(v => {
            const node = graph.node(v) as NodeLabel;
            if (rankAlign === "top") {
                node.y = prevY + node.height / 2;
            } else if (rankAlign === "bottom") {
                node.y = prevY + maxHeight - node.height / 2;
            } else {
                node.y = prevY + maxHeight / 2;
            }
        });
        prevY += maxHeight + rankSep;
    });
}

import * as acyclic from "./acyclic";
import * as normalize from "./normalize";
import rank from "./rank";
import * as util from "./util";
import {normalizeRanks, removeEmptyRanks} from "./util";
import parentDummyChains from "./parent-dummy-chains";
import * as nestingGraph from "./nesting-graph";
import addBorderSegments from "./add-border-segments";
import * as coordinateSystem from "./coordinate-system";
import order from "./order";
import {position} from "./position";
import {Graph} from "./graph-lib";
import type {Edge, EdgeLabel, GraphLabel, LayoutOptions, NodeCollection, NodeLabel, Point} from "./types";

interface SelfEdge {
    e: Edge;
    label: EdgeLabel;
}

interface ExtendedNodeLabel extends NodeLabel {
    selfEdges?: SelfEdge[];
}

/** Internal-only: cluster node label augmented with a transient subgraph reference used during layout. */
interface ClusterNodeLabel extends NodeLabel {
    _dagreClusterSubgraph?: Graph<GraphLabel, NodeLabel, EdgeLabel>;
}

interface SelfEdgeNodeLabel extends Omit<NodeLabel, 'e' | 'label'> {
    e: Edge;
}

interface EdgeProxyNodeLabel extends Omit<NodeLabel, 'e'> {
    e: Edge;
}

interface PreviousLayout {
    graph: Graph<GraphLabel, NodeLabel, EdgeLabel>;
    rawNodes: NodeCollection;
}

// Remember layout state per input graph so unrelated callers cannot affect each other.
const previousLayouts = new WeakMap<Graph<GraphLabel, NodeLabel, EdgeLabel>, PreviousLayout>();

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function layout<G = any, N = any, E = any>(g: Graph<G, N, E>, opts: LayoutOptions = {}): Graph<G, N, E> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    recursiveClusterLayout(g as any, util.notime, opts);
    return g;
}

/** Returns the direct child of `cluster` that is an ancestor-or-equal of `node`, or undefined. */
function topLevelChildOf(g: Graph<GraphLabel, NodeLabel, EdgeLabel>, node: string, cluster: string): string | undefined {
    let current: string | undefined = node;
    while (current !== undefined) {
        const parent = g.parent(current) as string | undefined;
        if (parent === cluster) return current;
        current = parent;
    }
    return undefined;
}

// Recursively layout clusters/subgraphs with their own rankdir
function recursiveClusterLayout(g: Graph<GraphLabel, NodeLabel, EdgeLabel>, time: <T>(name: string, fn: () => T) => T, opts: LayoutOptions): void {
    // Find clusters (nodes with children)
    const clusterNodes: string[] = g.nodes().filter(v => g.children(v).length);
    // Map of cluster id to bounding box and offset
    const clusterBounds: Record<string, {minX: number, minY: number, maxX: number, maxY: number, width: number, height: number, offsetX: number, offsetY: number}> = {};

    // First, recursively layout all clusters with their own rankdir
    clusterNodes.forEach(v => {
        const node = g.node(v);
        if (node && node.rankdir) {
            // Build a new graph for the cluster's subgraph
            const subgraph = new Graph<GraphLabel, NodeLabel, EdgeLabel>({ multigraph: true, compound: true });
            // Set the subgraph's direction on the graph label
            subgraph.setGraph({ rankdir: node.rankdir });
            // Copy nodes and edges belonging to this cluster
            const children = g.children(v);
            children.forEach(childId => {
                const childNode = { ...g.node(childId) };
                subgraph.setNode(childId, childNode);
                // Set parent if needed (for nested clusters)
                const parent = g.parent(childId);
                if (parent && parent !== v && children.includes(parent)) {
                    subgraph.setParent(childId, parent);
                }
            });
            // Copy edges between the cluster's direct children, treating edges whose endpoints
            // are inside a nested sub-cluster as proxy edges from that sub-cluster node.
            const proxiedEdges = new Set<string>();
            g.edges().forEach(e => {
                const srcChild = topLevelChildOf(g, e.v, v);
                const tgtChild = topLevelChildOf(g, e.w, v);
                if (srcChild && tgtChild && srcChild !== tgtChild) {
                    const key = `${srcChild}\x00${tgtChild}`;
                    if (!proxiedEdges.has(key)) {
                        proxiedEdges.add(key);
                        subgraph.setEdge(srcChild, tgtChild, { ...g.edge(e) });
                    }
                }
            });
            // Recursively layout the subgraph (with its own rankdir)
            recursiveClusterLayout(subgraph, time, opts);
            // Run the layout pipeline on the subgraph via a proper layout graph
            const subLayoutG = buildLayoutGraph(subgraph);
            runLayout(subLayoutG, time, opts, null);
            updateInputGraph(subgraph, subLayoutG);
            // Compute bounding box for the cluster
            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            subgraph.nodes().forEach((u: string) => {
                if (u === v) return; // skip cluster node itself
                const n = subgraph.node(u);
                if (n && typeof n.x === 'number' && typeof n.y === 'number' && typeof n.width === 'number' && typeof n.height === 'number') {
                    minX = Math.min(minX, n.x - n.width / 2);
                    maxX = Math.max(maxX, n.x + n.width / 2);
                    minY = Math.min(minY, n.y - n.height / 2);
                    maxY = Math.max(maxY, n.y + n.height / 2);
                }
            });
            // Fallback if no children
            if (!isFinite(minX) || !isFinite(minY) || !isFinite(maxX) || !isFinite(maxY)) {
                minX = minY = 0; maxX = maxY = 0;
            }
            const width = maxX - minX;
            const height = maxY - minY;
            // Store bounding box and offset for this cluster
            clusterBounds[v] = {
                minX, minY, maxX, maxY, width, height,
                offsetX: minX, offsetY: minY
            };
            // Save the internal layout for later
            (node as ClusterNodeLabel)._dagreClusterSubgraph = subgraph;
        }
    });

    // Strict isolation: run cluster layout in a separate graph, only position as a group in parent
    const isolatedClusters: Array<{
        clusterId: string,
        subgraph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
        bounds: {minX: number, minY: number, maxX: number, maxY: number, width: number, height: number},
        children: string[],
        removedNodes: Array<{id: string, node: NodeLabel, parent: string | undefined}>,
        removedEdges: Array<{edge: Edge, label: EdgeLabel}>,
    }> = [];

    // --- Step 1: collect top-level clusters with ALL their descendants (BFS) ---
    // Nested cluster nodes (themselves children of another cluster) are handled via
    // the parent cluster's subgraph + the second pass below, not isolated here.
    const getAllDescendants = (nodeId: string): string[] => {
        const result: string[] = [];
        const queue: string[] = ((g.children(nodeId) || []) as string[]).filter(c => c !== nodeId);
        while (queue.length > 0) {
            const curr = queue.shift()!;
            result.push(curr);
            ((g.children(curr) || []) as string[]).filter(c => c !== curr).forEach(c => queue.push(c));
        }
        return result;
    };
    const rawClusterMap = new Map<string, string[]>();
    clusterNodes.forEach(v => {
        const node = g.node(v);
        if (node && node.rankdir && clusterBounds[v]) {
            rawClusterMap.set(v, ((g.children(v) || []) as string[]).filter(c => c !== v));
        }
    });
    // A cluster that is a direct child of another cluster is nested — skip it here
    const allDirectChildrenFlat = new Set<string>([...rawClusterMap.values()].flat());
    const clusterChildrenMap = new Map<string, string[]>();
    rawClusterMap.forEach((_, v) => {
        if (!allDirectChildrenFlat.has(v)) {
            // Top-level cluster: include ALL descendants so orphaned grandchildren are removed too
            clusterChildrenMap.set(v, getAllDescendants(v));
        }
    });
    const allIsolatedChildren = new Set<string>(
        [...clusterChildrenMap.values()].flat()
    );
    // Resolve a node to its top-level cluster representative (or itself if not a child)
    const topLevelNode = (id: string): string => {
        for (const [cId, ch] of clusterChildrenMap) {
            if (ch.includes(id)) return cId;
        }
        return id;
    };

    // --- Step 2: save edges incident to any isolated child BEFORE removing any node ---
    const allSavedEdges: Array<{edge: Edge, label: EdgeLabel}> = [];
    g.edges().forEach(e => {
        if (allIsolatedChildren.has(e.v) || allIsolatedChildren.has(e.w)) {
            allSavedEdges.push({edge: e, label: g.edge(e)});
        }
    });

    // --- Step 3: remove cluster children, record per-cluster metadata ---
    // Pre-save parent info before any removals; g.removeNode() may re-parent children
    const savedParents = new Map<string, string | undefined>();
    allIsolatedChildren.forEach(id => {
        const p = g.parent(id);
        savedParents.set(id, typeof p === 'string' ? p : undefined);
    });
    clusterChildrenMap.forEach((children, v) => {
        const node = g.node(v);
        const removedNodes: Array<{id: string, node: NodeLabel, parent: string | undefined}> = [];
        children.forEach(childId => {
            const childNode = g.node(childId);
            if (!childNode) return; // already removed (e.g. inner cluster's children after inner was removed)
            removedNodes.push({id: childId, node: childNode, parent: savedParents.get(childId)});
            g.removeNode(childId); // graphlib also removes incident edges here
        });
        const removedEdges = allSavedEdges.filter(({edge}) =>
            children.includes(edge.v) || children.includes(edge.w)
        );
        const bounds = clusterBounds[v]!;
        if (!node) return;
        isolatedClusters.push({
            clusterId: v,
            subgraph: (node as ClusterNodeLabel)._dagreClusterSubgraph!,
            bounds,
            children,
            removedNodes,
            removedEdges,
        });
        // Set the cluster node's width/height for parent layout
        node.width = bounds.width;
        node.height = bounds.height;
    });

    // --- Step 4: add proxy edges between cluster nodes so the parent layout respects ordering ---
    const proxyEdgeKeys = new Set<string>();
    allSavedEdges.forEach(({edge, label}) => {
        const effV = topLevelNode(edge.v);
        const effW = topLevelNode(edge.w);
        if (effV !== effW && g.hasNode(effV) && g.hasNode(effW)) {
            const key = `${effV}\x00${effW}`;
            if (!proxyEdgeKeys.has(key)) {
                proxyEdgeKeys.add(key);
                g.setEdge(effV, effW, {...label, width: 0, height: 0});
            }
        }
    });

    // --- Step 5: run the main layout for the top-level graph ---
    const layoutG = buildLayoutGraph(g);
    const result = runLayout(layoutG, time, opts, previousLayouts.get(g) ?? null);
    previousLayouts.set(g, result);
    updateInputGraph(g, layoutG);

    // --- Step 6: remove proxy edges, restore cluster internals, position children ---
    // Remove proxy edges before restoring original edges
    proxyEdgeKeys.forEach(key => {
        const sep = key.indexOf('\x00');
        const effV = key.slice(0, sep);
        const effW = key.slice(sep + 1);
        if (g.hasEdge(effV, effW)) g.removeEdge(effV, effW);
    });

    // Restore all clusters' internal nodes and edges, and position them as a group
    isolatedClusters.forEach(({clusterId, subgraph, bounds, removedNodes, removedEdges}) => {
        // Get cluster node position from parent layout
        const clusterNode = g.node(clusterId);
        const clusterX = clusterNode?.x ?? 0;
        const clusterY = clusterNode?.y ?? 0;
        // Compute the center of the subgraph's bounding box
        const subgraphCenterX = (bounds.minX + bounds.maxX) / 2;
        const subgraphCenterY = (bounds.minY + bounds.maxY) / 2;
        // Restore internal nodes
        removedNodes.forEach(({id, node, parent}) => {
            g.setNode(id, node);
            if (parent !== undefined) g.setParent(id, parent);
        });
        // Restore internal edges
        removedEdges.forEach(({edge, label}) => {
            g.setEdge(edge, label);
        });
        // Offset all child nodes (except the cluster node itself) as a group
        subgraph.nodes().forEach((u: string) => {
            if (u === clusterId) return;
            const subNode = subgraph.node(u);
            const mainNode = g.node(u);
            if (
                mainNode && subNode &&
                typeof subNode.x === 'number' && typeof subNode.y === 'number'
            ) {
                mainNode.x = clusterX + (subNode.x - subgraphCenterX);
                mainNode.y = clusterY + (subNode.y - subgraphCenterY);
            }
        });
        delete (clusterNode as ClusterNodeLabel)._dagreClusterSubgraph;
    });

    // After parent layout, forcibly swap x/y for cluster children if needed
    clusterNodes.forEach(v => {
        const node = g.node(v);
        const bounds = clusterBounds[v];
        if (node && node.rankdir && (node as ClusterNodeLabel)._dagreClusterSubgraph && bounds) {
            const subgraph = (node as ClusterNodeLabel)._dagreClusterSubgraph as Graph<GraphLabel, NodeLabel, EdgeLabel>;
            // Find where the parent layout placed the cluster node
            const parentX = node.x ?? 0;
            const parentY = node.y ?? 0;
            // Compute the center of the subgraph's bounding box
            const subgraphCenterX = (bounds.minX + bounds.maxX) / 2;
            const subgraphCenterY = (bounds.minY + bounds.maxY) / 2;
            // Offset all child nodes (except the cluster node itself)
            subgraph.nodes().forEach((u: string) => {
                if (u === v) return;
                const subNode = subgraph.node(u);
                const mainNode = g.node(u);
                if (
                    mainNode && subNode &&
                    typeof subNode.x === 'number' && typeof subNode.y === 'number'
                ) {
                    const dx = subNode.x - subgraphCenterX;
                    const dy = subNode.y - subgraphCenterY;
                    mainNode.x = parentX + dx;
                    mainNode.y = parentY + dy;
                }
            });
            // Optionally, clean up
            delete (node as ClusterNodeLabel)._dagreClusterSubgraph;
        }
    });
}

function runLayout(
    g: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    time: <T>(name: string, fn: () => T) => T,
    opts: LayoutOptions,
    previous: PreviousLayout | null = null
): PreviousLayout {
    const dynamic = opts?.useDynamic !== false;
    const oldGraph = dynamic ? previous?.graph ?? null : null;
    const rawOldNodes = dynamic ? previous?.rawNodes ?? null : null;
    time("    makeSpaceForEdgeLabels", () => makeSpaceForEdgeLabels(g));
    time("    removeSelfEdges", () => removeSelfEdges(g));
    time("    acyclic", () => acyclic.run(g, oldGraph));
    time("    nestingGraph.run", () => nestingGraph.run(g));
    time("    rank", () => rank(util.asNonCompoundGraph(g)));
    time("    injectEdgeLabelProxies", () => injectEdgeLabelProxies(g));
    time("    removeEmptyRanks", () => removeEmptyRanks(g));
    time("    nestingGraph.cleanup", () => nestingGraph.cleanup(g));
    time("    normalizeRanks", () => normalizeRanks(g));
    time("    assignRankMinMax", () => assignRankMinMax(g));
    time("    removeEdgeLabelProxies", () => removeEdgeLabelProxies(g));
    time("    normalize.run", () => normalize.run(g));
    time("    parentDummyChains", () => parentDummyChains(g));
    time("    addBorderSegments", () => addBorderSegments(g));
    time("    order", () => order(g, opts, rawOldNodes));
    time("    insertSelfEdges", () => insertSelfEdges(g));
    time("    adjustCoordinateSystem", () => coordinateSystem.adjust(g));
    time("    position", () => position(g, opts.corePath));
    time("    positionSelfEdges", () => positionSelfEdges(g));
    const rawNodes: NodeCollection = JSON.parse(JSON.stringify((g as unknown as { _nodes: NodeCollection })._nodes));
    time("    removeBorderNodes", () => removeBorderNodes(g));
    time("    normalize.undo", () => normalize.undo(g));
    time("    fixupEdgeLabelCoords", () => fixupEdgeLabelCoords(g));
    time("    undoCoordinateSystem", () => coordinateSystem.undo(g));
    time("    translateGraph", () => translateGraph(g));
    time("    assignNodeIntersects", () => assignNodeIntersects(g));
    time("    reversePoints", () => reversePointsForReversedEdges(g));
    time("    acyclic.undo", () => acyclic.undo(g));

    return {graph: g, rawNodes};
}

/*
 * Copies final layout information from the layout graph back to the input
 * graph. This process only copies whitelisted attributes from the layout graph
 * to the input graph, so it serves as a good place to determine what
 * attributes can influence layout.
 */
function updateInputGraph(
    inputGraph: Graph<GraphLabel, NodeLabel, EdgeLabel>,
    layoutGraph: Graph<GraphLabel, NodeLabel, EdgeLabel>
): void {
    inputGraph.nodes().forEach(v => {
        const inputLabel = inputGraph.node(v);
        const layoutLabel = layoutGraph.node(v);

        if (inputLabel) {
            inputLabel.x = layoutLabel.x;
            inputLabel.y = layoutLabel.y;
            inputLabel.order = layoutLabel.order;
            inputLabel.rank = layoutLabel.rank;

            if (layoutGraph.children(v).length) {
                inputLabel.width = layoutLabel.width;
                inputLabel.height = layoutLabel.height;
            }
        }
    });

    inputGraph.edges().forEach(e => {
        const inputLabel = inputGraph.edge(e);
        const layoutLabel = layoutGraph.edge(e);

        inputLabel.points = layoutLabel.points;
        if (Object.hasOwn(layoutLabel, "x")) {
            inputLabel.x = layoutLabel.x;
            inputLabel.y = layoutLabel.y;
        }
    });

    inputGraph.graph().width = layoutGraph.graph().width;
    inputGraph.graph().height = layoutGraph.graph().height;
}

const graphNumAttrs: string[] = ["nodesep", "edgesep", "ranksep", "marginx", "marginy"];
const graphDefaults: Partial<GraphLabel> = {ranksep: 50, edgesep: 20, nodesep: 50, rankdir: "TB", rankalign: "center"};
const graphAttrs: string[] = ["acyclicer", "ranker", "rankdir", "align", "rankalign"];
const nodeNumAttrs: string[] = ["width", "height", "rank"];
const nodeDefaults: Partial<NodeLabel> = {width: 0, height: 0};
const edgeNumAttrs: string[] = ["minlen", "weight", "width", "height", "labeloffset"];
const edgeDefaults: Partial<EdgeLabel> = {
    minlen: 1, weight: 1, width: 0, height: 0,
    labeloffset: 10, labelpos: "r"
};
const edgeAttrs: string[] = ["labelpos"];

/*
 * Constructs a new graph from the input graph, which can be used for layout.
 * This process copies only whitelisted attributes from the input graph to the
 * layout graph. Thus this function serves as a good place to determine what
 * attributes can influence layout.
 */
function buildLayoutGraph(inputGraph: Graph<GraphLabel, NodeLabel, EdgeLabel>): Graph<GraphLabel, NodeLabel, EdgeLabel> {
    const g = new Graph<GraphLabel, NodeLabel, EdgeLabel>({multigraph: true, compound: true});
    const graph = canonicalize(inputGraph.graph());

    g.setGraph(Object.assign({},
        graphDefaults,
        selectNumberAttrs(graph, graphNumAttrs),
        util.pick(graph, graphAttrs)));

    inputGraph.nodes().forEach(v => {
        const node = canonicalize(inputGraph.node(v));
        const newNode = selectNumberAttrs(node, nodeNumAttrs) as NodeLabel;
        Object.keys(nodeDefaults).forEach(k => {
            if (newNode[k] === undefined) {
                newNode[k] = (nodeDefaults)[k];
            }
        });

        g.setNode(v, newNode);
        const parent = inputGraph.parent(v);
        if (parent !== undefined) {
            g.setParent(v, parent);
        }
    });

    inputGraph.edges().forEach(e => {
        const edge = canonicalize(inputGraph.edge(e));
        g.setEdge(e, Object.assign({},
            edgeDefaults,
            selectNumberAttrs(edge, edgeNumAttrs),
            util.pick(edge, edgeAttrs)));
    });

    return g;
}

/*
 * This idea comes from the Gansner paper: to account for edge labels in our
 * layout we split each rank in half by doubling minlen and halving ranksep.
 * Then we can place labels at these mid-points between nodes.
 *
 * We also add some minimal padding to the width to push the label for the edge
 * away from the edge itself a bit.
 */
function makeSpaceForEdgeLabels(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const graph = g.graph();
    graph.ranksep! /= 2;
    g.edges().forEach(e => {
        const edge = g.edge(e);
        edge.minlen! *= 2;
        if ((edge.labelpos ?? "r").toLowerCase() !== "c") {
            if (graph.rankdir === "TB" || graph.rankdir === "BT") {
                edge.width! += edge.labeloffset!;
            } else {
                edge.height! += edge.labeloffset!;
            }
        }
    });
}

/*
 * Creates temporary dummy nodes that capture the rank in which each edge's
 * label is going to, if it has one of non-zero width and height. We do this
 * so that we can safely remove empty ranks while preserving balance for the
 * label's position.
 */
function injectEdgeLabelProxies(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.edges().forEach(e => {
        const edge = g.edge(e);
        if (edge.width && edge.height) {
            const v = g.node(e.v);
            const w = g.node(e.w);
            const label: Partial<NodeLabel> = {rank: (w.rank! - v.rank!) / 2 + v.rank!, e: e as unknown as number};
            util.addDummyNode(g, "edge-proxy", label, "_ep");
        }
    });
}

function assignRankMinMax(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    let maxRank = 0;
    g.nodes().forEach(v => {
        const node = g.node(v);
        if (node.borderTop) {
            node.minRank = g.node(node.borderTop).rank;
            node.maxRank = g.node(node.borderBottom!).rank;
            maxRank = Math.max(maxRank, node.maxRank!);
        }
    });
    g.graph().maxRank = maxRank;
}

function removeEdgeLabelProxies(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.nodes().forEach(v => {
        const node = g.node(v);
        if (node.dummy === "edge-proxy") {
            const proxyNode = node as unknown as EdgeProxyNodeLabel;
            g.edge(proxyNode.e).labelRank = node.rank;
            g.removeNode(v);
        }
    });
}

function translateGraph(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    let minX = Number.POSITIVE_INFINITY;
    let maxX = 0;
    let minY = Number.POSITIVE_INFINITY;
    let maxY = 0;
    const graphLabel = g.graph();
    const marginX = graphLabel.marginx || 0;
    const marginY = graphLabel.marginy || 0;

    function getExtremes(attrs: NodeLabel | EdgeLabel): void {
        const x = attrs.x!;
        const y = attrs.y!;
        const w = attrs.width!;
        const h = attrs.height!;
        minX = Math.min(minX, x - w / 2);
        maxX = Math.max(maxX, x + w / 2);
        minY = Math.min(minY, y - h / 2);
        maxY = Math.max(maxY, y + h / 2);
    }

    g.nodes().forEach(v => getExtremes(g.node(v)));
    g.edges().forEach(e => {
        const edge = g.edge(e);
        if (Object.hasOwn(edge, "x")) {
            getExtremes(edge);
        }
    });

    minX -= marginX;
    minY -= marginY;

    g.nodes().forEach(v => {
        const node = g.node(v);
        node.x! -= minX;
        node.y! -= minY;
    });

    g.edges().forEach(e => {
        const edge = g.edge(e);
        edge.points!.forEach(p => {
            p.x -= minX;
            p.y -= minY;
        });
        if (Object.hasOwn(edge, "x")) {
            edge.x! -= minX;
        }
        if (Object.hasOwn(edge, "y")) {
            edge.y! -= minY;
        }
    });

    graphLabel.width = maxX - minX + marginX;
    graphLabel.height = maxY - minY + marginY;
}

function assignNodeIntersects(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.edges().forEach(e => {
        if (e.v === e.w) return; // self-loops already have their full spline from positionSelfEdges
        const edge = g.edge(e);
        const nodeV = g.node(e.v);
        const nodeW = g.node(e.w);
        let p1: Point, p2: Point;
        if (!edge.points) {
            edge.points = [];
            p1 = nodeW as Point;
            p2 = nodeV as Point;
        } else {
            p1 = edge.points[0]!;
            p2 = edge.points[edge.points.length - 1]!;
        }
        edge.points.unshift(util.intersectRect(nodeV, p1));
        edge.points.push(util.intersectRect(nodeW, p2));
    });
}

function fixupEdgeLabelCoords(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.edges().forEach(e => {
        const edge = g.edge(e);
        if (Object.hasOwn(edge, "x")) {
            if (edge.labelpos === "l" || edge.labelpos === "r") {
                edge.width! -= edge.labeloffset!;
            }
            switch (edge.labelpos) {
            case "l":
                    edge.x! -= edge.width! / 2 + edge.labeloffset!;
                break;
            case "r":
                    edge.x! += edge.width! / 2 + edge.labeloffset!;
                break;
            }
        }
    });
}

function reversePointsForReversedEdges(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.edges().forEach(e => {
        const edge = g.edge(e);
        if (edge.reversed) {
            edge.points!.reverse();
        }
    });
}

function removeBorderNodes(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.nodes().forEach(v => {
        if (g.children(v).length) {
            const node = g.node(v);
            const t = g.node(node.borderTop!);
            const b = g.node(node.borderBottom!);
            const l = g.node(node.borderLeft![node.borderLeft!.length - 1]!);
            const r = g.node(node.borderRight![node.borderRight!.length - 1]!);

            node.width = Math.abs(r.x! - l.x!);
            node.height = Math.abs(b.y! - t.y!);
            node.x = l.x! + node.width / 2;
            node.y = t.y! + node.height / 2;
        }
    });

    g.nodes().forEach(v => {
        if (g.node(v).dummy === "border") {
            g.removeNode(v);
        }
    });
}

function removeSelfEdges(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.edges().forEach(e => {
        if (e.v === e.w) {
            const node = g.node(e.v) as ExtendedNodeLabel;
            if (!node.selfEdges) {
                node.selfEdges = [];
            }
            node.selfEdges.push({e: e, label: g.edge(e)});
            g.removeEdge(e);
        }
    });
}

function insertSelfEdges(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    const layers = util.buildLayerMatrix(g);
    layers.forEach(layer => {
        let orderShift = 0;
        layer.forEach((v, i) => {
            const node = g.node(v) as ExtendedNodeLabel;
            // Defensive: assign default rank/order if missing
            if (typeof node.rank !== 'number') node.rank = 0;
            node.order = i + orderShift;
            (node.selfEdges || []).forEach(selfEdge => {
                util.addDummyNode(g, "selfedge", {
                    width: selfEdge.label.width!,
                    height: selfEdge.label.height!,
                    rank: node.rank,
                    order: i + (++orderShift),
                    e: selfEdge.e as unknown as number,
                    edgeLabel: selfEdge.label
                }, "_se");
                // If points array is not set, assign a default 7-point spline
                if (!Array.isArray(selfEdge.label.points) || selfEdge.label.points.length !== 7) {
                    selfEdge.label.points = [
                        {x: 0, y: -10},
                        {x: 0, y: -10},
                        {x: 0, y: 0},
                        {x: 0, y: 10},
                        {x: 0, y: 10},
                        {x: 0, y: 0},
                        {x: 0, y: 0}
                    ];
                }
            });
            delete node.selfEdges;
        });
    });
}

function positionSelfEdges(g: Graph<GraphLabel, NodeLabel, EdgeLabel>): void {
    g.nodes().forEach(v => {
        const node = g.node(v);
        const valid = (val: unknown) => typeof val === 'number' && isFinite(val);
        if (node.dummy === "selfedge") {
            const selfEdgeNode = node as unknown as SelfEdgeNodeLabel & { edgeLabel: EdgeLabel };
            const selfNode = g.node(selfEdgeNode.e.v);
            const xVal = valid(selfNode?.x) ? selfNode.x! : 0;
            const yVal = valid(selfNode?.y) ? selfNode.y! : 0;
            const widthVal = valid(selfNode?.width) ? selfNode.width! : 0;
            const heightVal = valid(selfNode?.height) ? selfNode.height! : 0;
            const nodeX = valid(node.x) ? node.x! : xVal;
            const nodeY = valid(node.y) ? node.y! : yVal;
            const dx = widthVal / 2;
            const dy = heightVal / 2;
            selfEdgeNode.edgeLabel.points = [
                {x: nodeX + dx, y: nodeY - dy},
                {x: nodeX + dx, y: nodeY - dy},
                {x: nodeX,      y: nodeY},
                {x: nodeX - dx, y: nodeY + dy},
                {x: nodeX - dx, y: nodeY + dy},
                {x: nodeX,      y: nodeY},
                {x: nodeX,      y: nodeY}
            ];
            selfEdgeNode.edgeLabel.x = nodeX;
            selfEdgeNode.edgeLabel.y = nodeY;
            g.setEdge(selfEdgeNode.e, selfEdgeNode.edgeLabel);
            g.removeNode(v);
        } else if (node && Array.isArray((node as ExtendedNodeLabel).selfEdges)) {
            // If node has selfEdges but no dummy node was created, ensure points is a 7-point spline centered on node
            ((node as ExtendedNodeLabel).selfEdges as Array<{label: EdgeLabel}>).forEach((selfEdge: {label: EdgeLabel}) => {
                if (!Array.isArray(selfEdge.label.points) || selfEdge.label.points.length !== 7) {
                    const xVal = valid(node.x) ? node.x! : 0;
                    const yVal = valid(node.y) ? node.y! : 0;
                    const widthVal = valid(node.width) ? node.width! : 0;
                    const heightVal = valid(node.height) ? node.height! : 0;
                    const dx = widthVal / 2;
                    const dy = heightVal / 2;
                    selfEdge.label.points = [
                        {x: xVal + dx, y: yVal - dy},
                        {x: xVal + dx, y: yVal - dy},
                        {x: xVal,      y: yVal},
                        {x: xVal - dx, y: yVal + dy},
                        {x: xVal - dx, y: yVal + dy},
                        {x: xVal,      y: yVal},
                        {x: xVal,      y: yVal}
                    ];
                }
            });
        }
    });
}

function selectNumberAttrs(obj: Record<string, unknown>, attrs: string[]): unknown {
    return util.mapValues(util.pick(obj, attrs), Number);
}

function canonicalize(attrs: Record<string, unknown>): Record<string, unknown> {
    const newAttrs: Record<string, unknown> = {};
    if (attrs) {
        Object.entries(attrs).forEach(([k, v]) => {
            if (typeof k === "string") {
                k = k.toLowerCase();
            }

            newAttrs[k] = v;
        });
    }
    return newAttrs;
}

import * as util from './util';
import {Graph} from "./graph-lib";
import type {NodeLabel} from './types';

export function debugOrdering(graph: Graph): Graph {
    const layerMatrix = util.buildLayerMatrix(graph);

    const h = new Graph({compound: true, multigraph: true}).setGraph({});

    graph.nodes().forEach(node => {
        h.setNode(node, {label: node});
        h.setParent(node, 'layer' + (graph.node(node) as NodeLabel).rank);
    });

    graph.edges().forEach(edge => h.setEdge(edge.v, edge.w, {}, edge.name));

    layerMatrix.forEach((layer, i) => {
        const layerV = 'layer' + i;
        h.setNode(layerV, {rank: 'same'});
        layer.reduce((u, v) => {
            h.setEdge(u, v, {style: 'invis'});
            return v;
        });
    });

    return h;
}

